import { useState, useEffect, useMemo, useRef } from "react";
import { Card, Grid, Input, Select, Spin } from "antd";

//const PROGRAMS_DATA = [{"name":"Agricultural Conservation Easement Program-Wetland Reserve Easements (ACEP-WRE)","livestock":0,"annualCrops":0,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":1,"supportType":"Conservation Cost Share","droughtScore":1,"notes":"Wetland restoration; supports water storage but not drought-targeted","details":{"introduction":"Wetlands Reserve Easements (WRE) help private and tribal landowners protect, restore and enhance wetlands which have been previously degraded due to agricultural uses. \n\nWetland Reserve Easements component of the Agricultural Conservation Easement Program provides habitat for migratory waterfowl and other wetland dependent wildlife, including threatened and endangered species; improves water quality by filtering sediments and chemicals; reduces flooding; recharges groundwater; protects biological diversity; and provides opportunities for educational, scientific and limited recreational activities.","eligibility":"Who is eligible?\nEligible landowners include:\nOwners of privately held land including land that is held by American Indian tribes.\nAll landowners who meet the adjusted gross income (AGI) limitations, including all members of landowner-legal entities, and those compliant with the Highly Erodible Land and Wetland Conservation provisions of the Food Security Act of 1985. \n\n What land is eligible?\nLand eligible for wetland reserve easements includes privately held farmed or converted wetlands that were previously degraded due to agricultural uses and can be successfully and cost-effectively restored. NRCS will prioritize applications based the easement\u2019s potential for protecting and enhancing habitat for migratory birds and other wildlife.","terms":"To enroll land through wetland reserve easements, NRCS enters into purchase agreements with eligible private landowners or Indian tribes that include the right for NRCS to develop and implement a Wetland Reserve Plan of Operations (WRPO). This plan will detail practices to help restore, protect and enhance the wetlands functions and values.\n\nWetland Reserve enrollment options include:\n\n\u25cf Permanent Easements \u2013 Permanent easements are conservation easements in perpetuity. NRCS pays 100 percent of the easement value for the purchase of the easement. Additionally, NRCS pays between 75 to 100 percent of the restoration costs.\n\n\u25cf30-year Easements \u2013 30-year easements expire after 30 years. Under 30-year easements, NRCS pays 50 to 75 percent of the easement value for the purchase of the easement. Additionally, NRCS pays between 50 to 75 percent of the restoration costs.  \n\n\u25cfTerm Easements - Term easements are easements that are for the maximum duration allowed under applicable State laws. NRCS pays 50 to 75 percent of the easement value for the purchase of the term easement. Additionally, NRCS pays between 50 to 75 percent of the restoration costs.\n\n\u25cf 30-year Contracts \u2013 30-year contracts are only available to enroll acreage owned by Indian tribes and program payment rates are commensurate with 30-year easements.\n\nFor all Wetland Reserve Easements options, NRCS pays all costs associated with recording the easement in the local land records office, including recording fees, charges for abstracts, survey and appraisal fees and title insurance.","applicationInstructions":"https://www.nrcs.usda.gov/sites/default/files/2022-09/how-to-get-assistance.pdf\n\n\nhttps://www.nrcs.usda.gov/getting-assistance/financial-help/applications-and-forms#:~:text=CPA%2D41%20Application%20Form%20for%20Entities","resources":"EPD Area Wide Market Analysis: Statement of Work Overview \u2014 This is a required training for all appraisers who will be conducting an Area Wide Market Analysis for the NRCS.","factSheet":"https://www.nrcs.usda.gov/sites/default/files/2022-10/Easements%20ACEP%20WRE.pdf","programWebpage":"https://www.nrcs.usda.gov/programs-initiatives/wetland-reserve-easements","organization":"Natural Resources Conservation Service"}},{"name":"Agricultural Conservation Easement Program: Agricultural Land Easements (ACEP-ALE)","livestock":1,"annualCrops":1,"specialtyCrops":1,"forageHayPasture":1,"forestry":0,"irrigatedPerennial":1,"mixedOperations":1,"supportType":"Conservation Cost Share","droughtScore":0,"notes":"Land protection; no direct drought function","details":{"introduction":"Agricultural Land Easements help private and tribal landowners, land trusts, and other entities such as state and local governments protect croplands and grasslands on working farms and ranches by limiting non-agricultural uses of the land through conservation easements. \n\nThe Agricultural Land Easements component of the Agricultural Conservation Easement Program protects the long-term viability of the nation\u2019s food supply by preventing conversion of productive working lands to non-agricultural uses. Land protected by agricultural land easements provides additional public benefits, including environmental quality, historic preservation, wildlife habitat and protection of open space. Additionally, Agricultural Land Easements leverage local partnerships to match NRCS funding and local partners are responsible for the long-term stewardship of the easement.\n","eligibility":"Who is eligible?\n\u25cfEligible partners include American Indian tribes, state and local governments and non-governmental organizations that have farmland, rangeland or grassland protection programs.\n\u25cfEligible landowners include owners of privately held land including land that is held by tribes and tribal members.\n\u25cfAll landowners, including required members of landowner-legal entities, must meet adjusted gross income (AGI) limitations and must be compliant with the HEL/WC provisions of the Food Security Act of 1985.\n\nWhat land is eligible?\nLand eligible for agricultural easements includes private or Tribal land that is agricultural land, cropland, rangeland, grassland, pastureland and nonindustrial private forest land. NRCS will prioritize applications that protect agricultural uses and related conservation values of the land and those that maximize the protection of contiguous acres devoted to agricultural use, including land on a farm or ranch.\n\nEligible Land Types must also meet one of the four following land eligibility criteria:\n\n\u25cfParcels enrolled to protect Prime, Unique, or Other productive soil.\n\u25cfParcels enrolled to provide protection of grazing uses and related conservation values.\n\u25cfParcels containing historical or archeological resources.\n\u25cfLand that furthers a state or local policy consistent with the purposes of ACEP-ALE.","terms":"NRCS provides financial assistance to eligible partners for purchasing Agricultural Land Easements that protect the agricultural use and conservation values of eligible land.\n\nFor working farms, the program helps farmers and ranchers keep their land in agriculture. Under the Agricultural Land\u2004Easement component, NRCS may contribute up to 50 percent of the fair market value of the agricultural land easement.\n\nThe program also protects grazing uses and related conservation values by conserving grassland, including rangeland, pastureland and shrubland. Where NRCS determines that grasslands of special environmental significance will be protected, NRCS may contribute up to 75 percent of the fair market value of the agricultural land easement.\n\nAgricultural Land Easements are permanent or for the maximum term allowed by law.","applicationInstructions":"Landowners - to learn more about both ALE and WRE, contact your local\u2004NRCS office. An NRCS conservationist will visit you and evaluate your land to help you determine eligibility for the various components of ACEP. If your land is eligible for ALE and you are looking for an eligible entity to hold your conservation easement; please visit\n\u2022\thttps://farmlandinfo.org/farmland-protection-directory/     \n\u2022\thttps://www.findalandtrust.org/ \n    \nEligible Entities - to learn more about Agricultural Land Easements, please contact your NRCS state office(https://www.nrcs.usda.gov/state-offices/state-offices) programs staff to inquire about how you can partner with NRCS to enroll conservation easements on eligible land.\nhttps://www.nrcs.usda.gov/getting-assistance/financial-help/applications-and-forms#:~:text=CPA%2D41%20Application%20Form%20for%20Entities\n\nhttps://www.nrcs.usda.gov/getting-assistance/financial-help/applications-and-forms#:~:text=CPA%2D41%20Application%20Form%20for%20Entities\n","resources":"https://farmlandinfo.org/farmland-protection-directory/\n\nhttps://landtrustalliance.org/land-trusts\n","factSheet":"https://www.nrcs.usda.gov/sites/default/files/2022-10/Easements%20ACEP%20Right%20For%20Me%20factsheet.pdf","programWebpage":"https://www.nrcs.usda.gov/programs-initiatives/ale-agricultural-land-easements","organization":"Natural Resources Conservation Service"}},{"name":"Conservation Reserve Enhancement Program (CREP)","livestock":0,"annualCrops":1,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":1,"supportType":"Conservation Cost Share","droughtScore":1,"notes":"Can improve water/soil conditions depending on project","details":{"introduction":"The Conservation Reserve Enhancement Program (CREP) is an offshoot of the Conservation Reserve Program (CRP), administered by the Farm Service Agency (FSA) in partnership with states, Tribal governments, and non-governmental organizations.  \n\nPartners work with FSA to develop CREP agreements designed to address specific conservation challenges in targeted geographic areas. The program encourages farmers and landowners to enroll in long-term conservation contracts, removing environmentally sensitive land from agricultural production and implementing conservation practices. Participants receive annual rental payments, cost-share assistance for establishing conservation practices, and other financial incentives. \n\nBenefits \nTargeted Environmental Impact: CREP focuses on addressing specific environmental issues in targeted areas, leading to more significant and measurable conservation outcomes.\n\nEconomic Support: Provides stable income to participants through annual rental payments and financial incentives, helping to support the economic viability of their operations.\n\nCommunity and Ecological Benefits: Enhances local water quality, reduces soil erosion, and creates wildlife habitat, benefiting the broader community and ecosystem.","eligibility":"Who Is Eligible\nEligible applicants include farmers and landowners with land in designated CREP project areas. The land must meet specific criteria related to environmental sensitivity and conservation potential. Participants must demonstrate the ability to implement and maintain the proposed conservation practices. \n\nImportant Dates\nEnrollment periods vary depending on the specific CREP project. Interested participants should contact their local FSA office for details on current and upcoming enrollment opportunities. ","terms":"Enrollment Options: CREP targets high-priority conservation issues, such as water quality improvement, soil erosion control, and enhancement of wildlife habitat, in a designated CREP project area. Participation involves long-term commitments, typically 10 to 15 years.\n\nPayments: Annual rental payments based on soil productivity and local rental rates. Cost-share assistance for up to 50% of the costs of establishing approved conservation practices. Additional financial incentives may be available for specific conservation practices or project areas.\n\nConservation Practices: Includes planting native grasses, trees, and other vegetation to improve water quality, control soil erosion, and enhance wildlife habitat. ","applicationInstructions":"To apply for the Conservation Reserve Enhancement Program, producers and landowners with land in a designated CREP project area must submit an offer to their local FSA office. The offer process includes providing information about the land, conservation goals, and the desired conservation practices. Detailed enrollment instructions and deadlines are available through the local FSA office. ","resources":"","factSheet":"https://www.fsa.usda.gov/tools/informational/fact-sheets/conservation-reserve-enhancement-program-crep","programWebpage":"https://www.fsa.usda.gov/resources/programs/conservation-reserve-enhancement-program-crep","organization":"Farm Service Agency"}},{"name":"Conservation Reserve Program (CRP)","livestock":0,"annualCrops":1,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":1,"supportType":"Conservation Cost Share","droughtScore":1,"notes":"Reduces erosion, improves soil moisture retention","details":{"introduction":"The Conservation Reserve Program (CRP), administered by the Farm Service Agency (FSA), is a voluntary program that encourages agricultural producers and landowners to convert highly erodible and other environmentally sensitive acreage to vegetative cover, such as native grasses, trees, and riparian buffers.  \n\nBy enrolling in CRP, participants receive annual rental payments and cost-share assistance to establish long-term, resource-conserving vegetative covers. The program helps to improve water quality, control soil erosion, and enhance wildlife habitat, contributing to overall environmental health and sustainability.\n\nBenefits:\nEnvironmental Improvements: CRP helps reduce soil erosion, improve water quality, and increase wildlife habitat, contributing to the overall health of ecosystems.\n\nEconomic Support: Annual rental payments provide a steady income stream for participants, helping to stabilize farm income. ","eligibility":"Agricultural producers and landowners with environmentally sensitive land that meets specific criteria related to cropping history and environmental characteristics are eligible. Applicants must demonstrate the potential for significant environmental benefits through the implementation of conservation practices. \n","terms":"Enrollment Options\n\nGeneral CRP : Annual signups where offers are ranked and selected based on environmental benefits.\n\nContinuous CRP:  Allows enrollment of eligible land without competitive ranking. This includes high-priority practices like filter strips, riparian buffers, and grass waterways.\nState Acres for Wildlife Enhancement (SAFE) Initiative\nHighly Erodible Land Initiative (HELI)\nClean Lakes, Estuaries and River Initiative (CLEAR30)\nFarmable Wetland Programs (FWP)\nConservation Reserve Enhancement Program (CREP)\n\nGrassland CRP: Focuses on preserving grasslands and promoting sustainable grazing practices. \n\nPayments\n\nParticipants receive annual rental payments based on soil productivity and the average cash rental rates in the county. Cost-share assistance is also available for up to 50% of the cost of establishing approved conservation practices.\n \nContract Duration  \n\nCRP contracts are typically 10 to 15 years in length, allowing time for significant environmental benefits to accrue.","applicationInstructions":"To apply for the Conservation Reserve Program, agricultural producers and landowners must submit an offer to their local FSA office. The offer process includes providing information about the land, conservation goals, and the desired conservation practices. Detailed enrollment instructions and deadlines are available through the local FSA office.","resources":"CRP General Signup Fact Sheet\n\nCRP General EBI Fact Sheet\u00a0\n\nCRP Continuous Signup Fact Sheet\n\nCRP State Acres for Wildlife Enhancement (SAFE) Initiative Fact Sheet\n\nCRP Clean Lakes Estuaries and Rivers (CLEAR) Initiative Fact Sheet\n\nCLEAR30 Fact Sheet\n\nHELI Fact Sheet\n\nPractices Library\u00a0\n\nEmergency Haying and Grazing\n\nConservation Reserve Program Statistics","factSheet":"https://www.fsa.usda.gov/tools/informational/fact-sheets/conservation-reserve-program-crp","programWebpage":"https://www.fsa.usda.gov/resources/programs/conservation-reserve-program","organization":"Farm Service Agency"}},{"name":"Conservation Stewardship Program (CSP)","livestock":1,"annualCrops":1,"specialtyCrops":1,"forageHayPasture":1,"forestry":1,"irrigatedPerennial":1,"mixedOperations":1,"supportType":"Conservation Cost Share","droughtScore":1,"notes":"Supports soil health and water retention practices","details":{"introduction":"The Conservation Stewardship Program (CSP) helps you build on your existing conservation efforts while strengthening your operation.  Whether you are looking to improve grazing conditions, increase crop resiliency, or develop wildlife habitat, NRCS can custom design a CSP plan to help you meet those goals. NRCS can help you identify natural resource problems in your operation and provide technical and financial assistance to solve those\u2004problems or attain higher stewardship levels in an environmentally beneficial and cost-effective manner. For example, NRCS can look at ways to address the amount of soil lost; mitigate the impact of excess water; reduce the contribution of agricultural operations to airborne soil particles and greenhouse gas emissions; improve the cover, food, and water available for domestic and wildlife species; or promote energy efficiencies for on-farm activities. If you are already taking steps to improve the condition of the land, chances are CSP can help you find new ways to meet your goals.\n\nBenefits:\n\nCSP is for working lands. It is the largest conservation program in the United States. Thousands of people voluntarily enroll in the program because it helps them enhance natural resources and improve their business operation.\n\nCSP participants are seeing real results.  Some of these benefits include:\n\n\u25cfEnhanced resiliency to weather and market volatility\n\u25cfDecreased need for agricultural inputs\n\u25cfImproved wildlife habitat conditions","eligibility":"Who is eligible? \nApplicants may include individuals, legal entities, jointoperations or Indian Tribes that own or rent and currentlymanage land for agricultural or forest production. Theapplicant must have a social security number or employeridentification number issued by the IRS and mustmaintain control of the land for the entire span of the5-year CSP contract. The applicant must have an adjustedgross income of less than $900,000. The adjusted grossincome requirement does not apply to Indian Tribes.\n\nWhat lands are eligible?\nEligible lands include private agricultural lands,agricultural Indian lands, nonindustrial private forestland, farmstead, associated agricultural lands and publicland that is under the control of the applicant andpart of their operation. There is no minimum acreagerequirement. CSP enrolls your entire operation into theprogram, not just one specific field or tract. All land mustbe in compliance with USDA highly erodible land andwetland conservation provisions tobe eligible for CSP.","terms":"If you are already taking steps to improve the condition of the land, chances are, CSP can help you find new ways to meet your goals.\n\nNRCS works one-on-one with producers to develop a conservation plan that outlines and enhances existing efforts, using new conservation practices or activities, based on management objectives for your operation. Producers implement practices and activities in their conservation plan that expands on the benefits of cleaner water and air, healthier soil and better wildlife habitat, all while improving their agricultural operations. \n\nFor example, if you have been planting a cover crop, you may decide to try an enhancement for a multi-species cover crop or implement a deep-rooted cover crop to break up soil compaction and further improve the health of your soil.\n\nCSP offers annual payments for implementing these practices on your land and operating and maintaining existing conservation efforts. Want to take it a step further? CSP also offers bundles where you can select a suite of enhancements and receive a higher payment rate.","applicationInstructions":"The first step in the process, is to notify NRCS of your interest in CSP.  Then a conservation planner will schedule a visit to your property. During that visit, they will walk the land with you to discuss and review any resource concerns.  Following the site visit, the conservation planner will develop a conservation plan that includes a variety of conservation practices, activities and enhancements to improve the level of conservation benefit and to address the resource concerns.\n\nApplications for NRCS conservation programs are accepted on a continuous basis. However, application ranking dates are set at key times throughout the year.\n\nFind application ranking dates for your state.\nSee payment schedules for your state.\nSee application.","resources":"","factSheet":"https://www.nrcs.usda.gov/sites/default/files/2025-05/nrcs-csp-right-for-me-factsheet-012025.pdf","programWebpage":"https://www.nrcs.usda.gov/programs-initiatives/conservation-stewardship-program","organization":"Natural Resources Conservation Service"}},{"name":"Environmental Quality Incentives Program (EQIP)","livestock":1,"annualCrops":1,"specialtyCrops":1,"forageHayPasture":1,"forestry":1,"irrigatedPerennial":1,"mixedOperations":1,"supportType":"Conservation Cost Share","droughtScore":1,"notes":"Funds irrigation efficiency, soil moisture, drought resilience","details":{"introduction":"The Environmental Quality Incentives Program (EQIP) is NRCS\u2019 flagship conservation program that helps farmers, ranchers and forest landowners integrate conservation into working lands.\n\nEQIP provides technical and financial assistance to agricultural producers and forest landowners to address natural resource concerns, such as:\nImproved water and air quality;\nConserved ground and surface water;\nIncreased soil health ;\nReduced soil erosion and sedimentation;\nImproved or created wildlife habitat; and\nMitigation against drought and increasing weather volatility.\n\nSome of these benefits include:\nReduced contamination from agricultural sources, such as animal feeding operations.\nEfficient use of nutrients, reducing input costs and reduction in nonpoint source pollution.\nImproved soil health, which mitigates against increasing weather volatility, improves drought resiliency.\nImplementation of practices that improve carbon sequestration and reduce greenhouse gas emissions while building resilient landscapes.","eligibility":"Farmers, ranchers, and forest landowners who own or rent agricultural land are eligible. EQIP assistance can be used on all types of agricultural operations, including:\n\nConventional and organic\nSpecialty crops and commodity crops\nForestry and wildlife\nHistorically underserved farmers*\nLivestock operations\n\n*Increased and advance payments available for historically underserved producers (beginning, limited resource, socially disadvantaged, and military veterans).","terms":"NRCS works one-on-one with producers to develop a conservation plan that outlines conservation practices and activities to help solve on-farm resource issues. Producers implement practices and activities in their conservation plan that can lead to cleaner water and air, healthier soil and better wildlife habitat, all while improving their agricultural operations. EQIP helps producers make conservation work for them. Financial assistance for practices may be available through EQIP.  Some producers may also qualify for advance payment.","applicationInstructions":"The first step is to contact your local NRCS office. An NRCS conservation planner will schedule a visit to your property. They will walk the land with you to discuss your goals and review any resource concerns. Following the site visit, the conservation planner will develop a conservation plan that includes a variety of conservation practices or activities to address the resource concerns and management goals discussed.\n\nApplications for NRCS conservation programs are accepted on a continuous basis; however, customers should apply by state-specific ranking dates to be considered for the current funding cycle.\n\nFind application ranking dates for your state.\nSee payment schedules for your state.\nSee application.\n\nTo learn more about EQIP, contact your local NRCS office.\n\nhttps://www.nrcs.usda.gov/getting-assistance/financial-help/applications-and-forms#:~:text=CPA%2D41%20Application%20Form%20for%20Entities","resources":"https://www.nrcs.usda.gov/sites/default/files/2022-10/Conservation%20Incentive%20Contracts.pdf","factSheet":"https://www.nrcs.usda.gov/sites/default/files/2025-01/nrcs-eqip-factsheet-2025-print-only.pdf","programWebpage":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program","organization":"Natural Resources Conservation Service"}},{"name":"Forest Legacy Program (FLP)","livestock":0,"annualCrops":0,"specialtyCrops":0,"forageHayPasture":0,"forestry":1,"irrigatedPerennial":0,"mixedOperations":1,"supportType":"Conservation Cost Share","droughtScore":0,"notes":"Forest conservation; not drought-focused","details":{"introduction":"The Forest Legacy Program is a conservation program administered by the Forest Service in partnership with State agencies to encourage the protection of privately owned forest lands through conservation easements or land purchases. Protection of private forests through FLP maintains a multitude of public benefits including:\n\nOpportunities to hunt, fish, and camp\nClean and abundant drinking water,\nHabitat for fish and wildlife, and\nTimber, fuel wood, and other forest products.","eligibility":"To be eligible for Oregon\u2019s FLP, proposed forestlandsmust 1) be located within the Forest Legacy Areasidentified by the state, 2) meet one or more ofOregon\u2019s goals identified in the Forest Action Plan,3) be privately owned and at least 75% forestland,5) be sponsored by a state agency, land trust, orconservation organization, 6) have a willing eligibleentity to hold title or land interests, and 7) secure aminimum of 25% non-federal match.\n\nIn addition, the purchase price must be based on aUS Federal Land Acquisition standard appraisal, andthe management must be guided by a Forest Serviceapproved management plan.","terms":"Each year, the Oregon Department of Forestrysolicits applications from eligible entities througha competitive, merit-based project selectionprocess coordinated through the U.S. ForestService. The projects are ranked and prioritizedby a state-led Forest Legacy StewardshipCommittee, and then submitted to the Region 6Forest Service. The final list of projects are sentto a National review panel, to be ranked andprioritized for consideration in the President\u2019sFiscal Year Budget.","applicationInstructions":"April: Forest Service Releases FY26 Call for Projects\n\nMay 15: Pre-application consultation with ODF\n\nJune 28: Forest Legacy project applicationsdue","resources":"","factSheet":"https://oregonlandtrusts.org/wp-content/uploads/2024/11/Forest-Legacy-One-Pager-April-2.pdf","programWebpage":"https://www.fs.usda.gov/managing-land/private-land/forest-legacy","organization":"Forest Service"}},{"name":"Healthy Forests Reserve Program","livestock":0,"annualCrops":0,"specialtyCrops":0,"forageHayPasture":0,"forestry":1,"irrigatedPerennial":0,"mixedOperations":1,"supportType":"Conservation Cost Share","droughtScore":0,"notes":"Focus on habitat, not drought","details":{"introduction":"The Healthy Forests Reserve Program (HFRP) helps landowners restore, enhance and protect forestland resources on private lands through easements and financial assistance. HRFP aids the recovery of\u2004endangered and threatened species under the Endangered Species Act, improves plant and animal biodiversity and enhances carbon sequestration.  \n\nBenefits:\nHFRP provides landowners with 10-year restoration agreements and 30-year or permanent easements for specific conservation actions. For acreage owned by an American Indian tribe, there is an additional enrollment option of a 30-year contract. Some landowners may avoid regulatory restrictions under the Endangered Species Act by restoring or improving habitat on their land for a specified period of time.","eligibility":"Who is eligible? \nBoth landowners and tenantscan participate in differentcomponents of HFRP.\n\nApplicants must provide proofof land ownership for easementenrollments or 30-year contractswith tribes.\n\nAn operator (tenant) mustprovide written concurrencefrom the landowner of tenancyfor the period of an HFRPrestoration agreement.\n\nWhat lands are eligible?\nTo be eligible for enrollment, land must be private land or tribal lands which\nwill restore, enhance, or measurably increase the likelihood of recovery of a threatened or endangered species, must improve biological diversity, or increase carbon sequestration.","terms":"The program offers four enrollment options:\n\nA 10-year restoration cost-shareagreement, for which the landownermay receive 50 percent of the averagecost of approved conservationpractices\n\nA 30-year easement, for which the landowner may receive 75 percent of the easement value of the enrolledland plus 75 percent of the average cost of approved conservation practices\n\nA 30-year contract on acreage owned by Indian tribes, for which the landowner may receive 75 percent of the contract value of the enrolled land plus 75 percent of the average cost of approved conservation practices\n\nA permanent easement, for which landowners may receive 100 percent of the easement value of the enrolledland plus 100 percent of the average cost of approved conservation practices","applicationInstructions":"To enroll in HFRP, landowners may apply at any time at\u00a0your local USDA Service Center.","resources":"https://www.nrcs.usda.gov/state-offices/north-dakota/healthy-forest-reserve-program","factSheet":"https://www.nrcs.usda.gov/sites/default/files/2024-02/National%20Easement_HFRP%20Factsheet_508.pdf","programWebpage":"https://www.nrcs.usda.gov/state-offices/north-dakota/healthy-forest-reserve-program","organization":"Natural Resources Conservation Service"}},{"name":"National Water Quality Initiative (NWQI)","livestock":1,"annualCrops":1,"specialtyCrops":1,"forageHayPasture":1,"forestry":0,"irrigatedPerennial":1,"mixedOperations":1,"supportType":"Conservation Cost Share","droughtScore":1,"notes":"Water-related; sometimes includes drought-relevant practices","details":{"introduction":"As USDA\u2019s premiere water quality initiative, National Water Quality Initiative (NWQI) provides a way to accelerate voluntary, on-farm conservation investments and focused water quality monitoring and assessment resources where they can deliver the greatest benefits for clean water.","eligibility":"NRCS provides targeted funding for financial and technical assistance in small watersheds most in need and where farmers can use conservation practices to make a difference.","terms":"Now in its eleventh year, the National Water Quality Initiative is a partnership among NRCS, state water quality agencies and the U.S. Environmental Protection Agency to identify and address impaired water bodies through voluntary conservation. NRCS provides targeted funding for financial and technical assistance in small watersheds most in need and where farmers can use conservation practices to make a difference.\n\nConservation systems include practices that promote soil health, reduce erosion and lessen nutrient runoff, such as filter strips, cover crops, reduced tillage and manure management. These practices not only benefit natural resources but enhance agricultural productivity and profitability by improving soil health and optimizing the use of agricultural inputs.\n\nState water quality agencies and other partners contribute additional resources for watershed planning, implementation and outreach. They also provide resources for monitoring efforts that help track water quality improvements over time.","applicationInstructions":"https://www.nrcs.usda.gov/programs-initiatives/national-water-quality-initiative#assistance","resources":"","factSheet":"","programWebpage":"https://ambrook.com/funding/national-water-quality-initiative","organization":"Natural Resources Conservation Service"}},{"name":"Partners for Fish & Wildlife Program (PFW)","livestock":1,"annualCrops":1,"specialtyCrops":1,"forageHayPasture":1,"forestry":0,"irrigatedPerennial":0,"mixedOperations":1,"supportType":"Conservation Cost Share","droughtScore":0,"notes":"Wildlife habitat focus","details":{"introduction":"The Partners for Fish and Wildlife Program provides free technical and financial assistance to landowners, managers, tribes, corporations, schools and nonprofits interested in improving wildlife habitat on their land. Since 1987, we have helped more than 25,000 landowners to complete more than 40,000 projects, restoring more than six million acres of forest, prairie, wetland and stream habitat for wildlife.","eligibility":"All private landowners interested in restoring wildlife habitat on their land are eligible to participate. Current partners include farmers, ranchers, forest landowners, recreational landowners, corporations, local governments and universities.","terms":"Priority goes to projects judged likely to provide habitat for rare, threatened and endangered species. Projects have a minimum duration of 10 years. In addition to private landowners, we partner with other federal agencies, state agencies and non-governmental organizations to complete projects on private lands.\n\nParticipating landowners do not forfeit any property rights and are not required to allow public access.\n\n","applicationInstructions":"A phone call or email is all it takes to get started. Contact your state coordinator to schedule an initial site visit and learn how Partners for Fish and Wildlife can help you","resources":"","factSheet":"","programWebpage":"https://www.fws.gov/program/partners-fish-and-wildlife","organization":"U.S. Fish & Wildlife Service"}},{"name":"Regional Conservation Partnership Program (RCPP)","livestock":1,"annualCrops":1,"specialtyCrops":1,"forageHayPasture":1,"forestry":1,"irrigatedPerennial":1,"mixedOperations":1,"supportType":"Conservation Cost Share","droughtScore":1,"notes":"Can include watershed/drought resilience projects","details":{"introduction":"The Regional Conservation PartnershipProgram (RCPP) promotes coordination ofNRCS conservation activities with partnersthat offer value-added contributions to expandour collective ability to address on-farm,watershed, and regional natural resourceconcerns. Through RCPP, NRCS seeks toco-invest with partners to implement projectsthat demonstrate innovative solutionsto conservation challenges and providemeasurable improvements and outcomes tiedto the resource concerns they seek to address.\n\nBenefits: RCPP makes available a variety of NRCSconservation activities to help partners, agproducers, and private landowners addresslocal and regional natural resource challenges.","eligibility":"Partner Eligibility:\n\nIndividual producers are not directly eligible for either RCPP program, however, they can apply as part of a producer organization. Producers seeking to carry out conservation activities consistent\u2004with a RCPP project in the project\u2019s geographic area can apply directly to NRCS.\n\nEntities that are classified as one of the following organizational types can serve as an eligible RCPP partner:\n\nAn agricultural or silvicultural producer association or other group of producers.\n\nA State or unit of local government.\n\nAn Indian Tribe.\n\nA farmer cooperative.\n\nA water district, irrigation district, acequia, rural water district or association, or other organization with specific water delivery authority to agricultural producers.\n\nA municipal water or wastewater treatment entity.\n\nAn institution of higher education.\n\nAn organization or entity with an established history of working cooperatively with producers on agricultural land, as determined by NRCS, to address\u2014\n\nLocal conservation priorities related to agricultural production, wildlife habitat development, or nonindustrial private forest land management; or\n\nCritical watershed-scale soil erosion, water quality, sediment reduction, or other natural resource issues.\n\nAn entity, such as an Indian Tribe, State government, local government, or a nongovernmental organization that has a farmland or grassland protection program that purchases agricultural land easements\n\nA conservation district.\n\nProducer and Landowner Eligibility:\n\nOnce NRCS selects a project and executes an RCPP agreement with a lead partner, agricultural producers may participate in an RCPP project in one of two ways. First, producers may engage with project partners and delegate a willing partner to act as their representative in working with NRCS. Second, producers seeking to carry out conservation activities consistent with a RCPP project in the project's geographic area can apply directly to NRCS.\n\nLand Eligibility:\n\nRCPP projects must be carried out on agricultural or nonindustrial private forest land or associated land on which NRCS determines an eligible activity would help achieve conservation benefits (i.e., improved condition of natural resources resulting from implementation of conservation activities).\n\nEligible conservation activities may be implemented on public lands when those activities will benefit eligible lands as determined by NRCS and are included in the scope of an approved RCPP project.","terms":"Step 1: Partners interested in submitting a proposal must obtain level 2 eAuthentication permissions. This process can be lengthy\u2004and is solely a partner responsibility. Partners are strongly encouraged to begin the eAuth process as soon as possible to minimize the possibility of the eAuth process creating a roadblock to RCPP proposal submission. Details on how to apply for eAuth permissions are in the RCPP Partner Proposal Guide.\n\nStep 2: Partners must request access to the RCPP portal . This process typically takes a few business days. During this process NRCS must verify a users\u2019 eAuth permissions and during high volume periods it may take over a week.\n\nStep 3: At least 4 weeks prior to the application deadline, and before starting an application in the RCPP portal, eligible entities interested in applying to RCPP are advised to request a meeting with the appropriate NRCS State RCPP coordinator(s).\n\nPartners are responsible for ensuring the above steps are completed early enough to meet the deadline for submitting an RCPP proposal. Most steps involve actions outside of NRCS and cannot be expedited.","applicationInstructions":"Interested partners must apply through theRCPP portal (nrcs.my.salesforce.com).\n\nOnce RCPP projects are selected, producersand landowners can apply to participate inprojects that cover their geographic area.Interested producers should visit their localUSDA Service Center to see if their landis included in the scope of any existingRCPP projects.","resources":"https://www.nrcs.usda.gov/wps/portal/nrcs/detail/national/programs/financial/rcpp/?cid=nrcseprd1564480","factSheet":"https://www.nrcs.usda.gov/sites/default/files/2022-06/NRCS-RCPP_FarmBill2018_Factsheet.pdf","programWebpage":"https://www.nrcs.usda.gov/programs-initiatives/regional-conservation-partnership-program","organization":"Natural Resources Conservation Service"}},{"name":"Sage Grouse Initiative (SGI)","livestock":1,"annualCrops":0,"specialtyCrops":0,"forageHayPasture":1,"forestry":0,"irrigatedPerennial":0,"mixedOperations":1,"supportType":"Conservation Cost Share","droughtScore":1,"notes":"Rangeland health; indirectly supports drought resilience","details":{"introduction":"The sage grouse, a chicken-like bird uniquely adapted to this habitat, is the poster child of the sagebrush country.\n\nThe sage grouse, a chicken-like bird uniquely adapted to this habitat, is the poster child of the sagebrush country and is best known for its early-morning dance during mating season.\n\nLarge-scale conversion of native rangelands to cultivated fields, housing and energy developments, invading conifers, and catastrophic wildfires have fragmented this vital landscape, reducing its size by half. And many species, including the sage grouse, have seen substantial declines from historic numbers as a result.\n\nStewardship-minded ranchers are helping reverse this decline by conserving and enhancing sagebrush habitat. And their conservation practices benefit more than just wildlife. They are improving the long-term sustainability of their grazing lands. As the saying goes, \u201cwhat\u2019s good for the bird is good for the herd.\u201d","eligibility":"Rancher or related private land owners.","terms":"Applications for most programs are accepted on a continuous basis, but they\u2019re considered for funding in different ranking periods. Be sure to ask your local NRCS district conservationist about the deadline for the ranking period to ensure you turn in your application in time.","applicationInstructions":"","resources":"","factSheet":"https://www.blm.gov/sites/blm.gov/files/OregonGrSGFactSheet.pdf","programWebpage":"https://www.nrcs.usda.gov/programs-initiatives/sage-grouse-initiative","organization":"Natural Resources Conservation Service"}},{"name":"State Acres for Wildlife Enhancement (SAFE)","livestock":0,"annualCrops":1,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":1,"supportType":"Conservation Cost Share","droughtScore":0,"notes":"Wildlife habitat","details":{"introduction":"The State Acres for Wildlife Enhancement (SAFE) Initiative restores vital habitat in order to meet high-priority state wildlife conservation goals. The Conservation Reserve Program (CRP) provides farmers and landowners with several opportunities like this to achieve many conservation goals. Through SAFE, landowners establish wetlands, grasses, and trees. These practices are designed to enhance important wildlife populations by creating critical habitat and food sources. They also protect soil and water health by working as a barrier to sediment and nutrient run-off before they reach waterways.\n\nFinancial Benefits:10\u201315 years of annualrental payments. Payments of up to 50%Cost-Share for practiceestablishment. Practices enrolled through ContinuousCRP Signup will also receive:A 50% Practice Incentive Payment(PIP). Signup IncentivePayment (SIP) equal to 32.5% of first fullyear\u2019s annual rentalpayment.","eligibility":"","terms":"","applicationInstructions":"","resources":"","factSheet":"https://www.fsa.usda.gov/tools/informational/fact-sheets/conservation-reserve-program-crp-state-acres-wildlife-enhancement","programWebpage":"https://www.fsa.usda.gov/resources/programs/conservation-programs/conservation-reserve-program/safe","organization":"Farm Service Agency"}},{"name":"Transition Incentives Program (TIP)","livestock":0,"annualCrops":1,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":1,"supportType":"Conservation Cost Share","droughtScore":0,"notes":"Land transition; not drought-focused","details":{"introduction":"The Transition Incentives Program (TIP) offers assistance for landowners and operators, as well as opportunities for beginning veteran and socially disadvantaged farmers and ranchers. It provides landowners or operators with two additional annual rental payments on land enrolled in expiring Conservation Reserve Program (CRP) contracts, on the condition they sell or rent this land to a beginning veteran or socially disadvantaged farmer or rancher. Up to two additional annual CRP payments can be obtained through TIP. New landowners or renters must return the land to production using sustainable grazing or farming methods.\n\nTIP provides landowners and operators with an incentive to return land to production on an expiring CRP Contract in a way that preserves established conservation practices. It also provides an opportunity for beginning, veteran and socially disadvantaged farmers and ranchers to purchase their own land or rent land.","eligibility":"Only land enrolled in an expiring CRP contract is eligible. TIP enrollment is on a continuous basis and may occur up to one year before a contract is set to expire. To qualify for TIP, the landowner or operator must either sell this land, or lease it on a long-term basis (at least five years), to a beginning veteran or socially disadvantaged farmer or rancher.\n\nNew owners and operators may also be eligible to enroll in the Conservation Stewardship Program or Environmental Quality Incentives Program, both initiatives of the USDA Natural Resources Conservation Service (NRCS).","terms":"Beginning farmer or rancher: a person or entity who has not been a farm or ranch operator for more than 10 years.\n\nVeteran farmer or rancher means a person, or for entities has at least 50 percent interest in that entity, who served in the Armed Forces and who has obtained status as a veteran during the most recent 10-year period, or operated a farm or ranch for no more than 10 years.\n\nSocially disadvantaged farmer or rancher: a farmer or rancher who is a member of a group whose members have historically been subjected to racial or ethnic prejudice because of their identity as a member of that group. For this program, gender is not included.","applicationInstructions":"For further information about the program, including CRP contract expiration rules, rental payment information, maintenance criteria, and land requirements, visit your local FSA office.","resources":"","factSheet":"https://www.fsa.usda.gov/Internet/FSA_File/tipfactsheet.pdf","programWebpage":"https://www.fsa.usda.gov/programs-and-services/conservation-programs/transition-incentives","organization":"Farm Service Agency"}},{"name":"Wetland Reserve Easement (WREP)","livestock":0,"annualCrops":0,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":1,"supportType":"Conservation Cost Share","droughtScore":1,"notes":"Wetland restoration; water storage benefits","details":{"introduction":"The Wetland Reserve Enhancement Partnership (WREP) is a voluntary program through which NRCS enters into agreements with eligible partners to leverage resources to carry out high priority wetland protection, restoration, and enhancement and to improve wildlife habitat.\n\nWetland Reserve Easements protect important wetlands within an agricultural landscape, provide habitat for fish and wildlife, including threatened and endangered species, improve water quality by filtering sediments and chemicals, reduce flooding, recharge groundwater, protect biological diversity and provide opportunities for educational, scientific and limited recreational activities.\n\nPartner benefits through WREP agreements include:\nWetland restoration and protection in areas where priorities align to enable greater impacts on the landscape;\nAbility to cost-share restoration or enhancement beyond NRCS requirements through leveraging;\nAbility to provide in-kind staff capacity for acquisition, due diligence and restoration activities.","eligibility":"Through WREP, under the Wetlands Reserve Easements component of ACEP, partners work with NRCS to help restore, protect and enhance enrolled wetlands directly with private landowners and Indian tribes through the purchase of an NRCS Wetland Reserve Easement. Eligible lands, which include farmed or converted wetland habitat that can be successfully and cost-effectively restored, may be enrolled\u2004under permanent easements, 30-year easements, or 30-year contracts (for acreage owned by Indian Tribes). For lands enrolled through wetland easements, NRCS will also develop and implement a Wetland Reserve Easement restoration plan that will restore, protect, and enhance the wetland\u2019s functions and values.\n\nPartner contributions must equal at least 10 percent of the total estimated costs for easement acquisition related costs and restoration implementation costs. Proposals that provide partner contributions greater than 10 percent will be given higher consideration in the selection process.","terms":"NRCS will prioritize applications for projects that:\n\nprovide maximum partner resources as match;\nsupport the goals and objectives of an NRCS Landscape Conservation Initiatives (see Priority Landscape Initiatives below);\nprotect habitat that benefits migratory birds and wetland-dependent wildlife;\nprovide direct benefits to federal and state threatened and endangered species; and\ninclude targeted outreach to underserved groups in the agricultural community.","applicationInstructions":"It is highly recommended that you work in collaboration with your local NRCS state office staff to develop your WREP proposal.","resources":"https://www.nrcs.usda.gov/ranking-dates","factSheet":"https://www.rwbjv.org/wp-content/uploads/WREP_Factsheet_2024.pdf","programWebpage":"https://www.nrcs.usda.gov/programs-initiatives/wetland-reserve-enhancement-partnership","organization":"Natural Resources Conservation Service"}},{"name":"Working Lands for Wildlife","livestock":1,"annualCrops":0,"specialtyCrops":0,"forageHayPasture":1,"forestry":0,"irrigatedPerennial":0,"mixedOperations":1,"supportType":"Conservation Cost Share","droughtScore":1,"notes":"Rangeland/ecosystem health supports drought resilience","details":{"introduction":"Through Working Lands for Wildlife (WLFW), USDA uses a win-win approach to systematically target conservation efforts to improve agricultural and forest productivity which enhance wildlife habitat on working landscapes.\u00a0","eligibility":"","terms":"Through WLFW, NRCS partners with the U.S. Fish and Wildlife Service to provide regulatory predictability under the Endangered Species Act. Similar to an insurance policy, predictability provides landowners with peace of mind that no matter the legal status of a species, they can keep their working lands working with an NRCS conservation plan in place.","applicationInstructions":"To apply for one of the sub-programs under WLFW, reach out to your local NRCS service center.","resources":"https://www.nrcs.usda.gov/conservation-basics/natural-resource-concerns/wildlife-habitat#assistance","factSheet":"","programWebpage":"https://www.nrcs.usda.gov/programs-initiatives/working-lands-for-wildlife","organization":"Natural Resources Conservation Service"}},{"name":"Cover Crops and Federal Crop Insurance","livestock":0,"annualCrops":1,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Crop & Livestock Insurance","droughtScore":1,"notes":"Soil moisture benefits + insurance linkage","details":{"introduction":"Cover crops and crop insurance have successfully coexisted, asevidenced by the rapid growth in the use of this agronomic practice. Asyou continue exploring the use of this conservation practice by plantingthe cover crop it is important that you review your crop insurance policyfor more information regarding cover crops, insurability, and goodfarming practices.\n\nFor crop insurance purposes, a cover crop is a crop generally recognizedby agricultural experts as agronomically sound in the area for erosioncontrol or other purposes for conservation or soil improvement. If youplant cover crops you may improve:\nWater use efficiency and quality improvements\nErosion Control\nSoil health improvement and nutrient cycling\nWeed and pest control\nAllelopathy\nHabitat for beneficial organisms","eligibility":"RMA does not have an approved list of cover crops. You should consultagricultural experts for which cover crops are agronomically sound forthe area for erosion control or other purposes related to conservation orsoil improvement. The Guidelines to provide a link to NRCS State FieldOffice Technical Guide for list of approved cover crop species:efotg.sc.egov.usda.gov/#/details(https://efotg.sc.egov.usda.gov/#/details)","terms":"For cash crops following cover crops, Risk Management Agency (RMA),Natural Resources Conservation Service (NRCS), and the Farm ServiceAgency (FSA) organized an interagency workgroup to develop aconsistent cover crop policy across the three agencies. The interagencygroup developed the NRCS Cover Crop Termination Guidelines(Guidelines), with the guiding principle that cover crops maximizeconservation benefits and increase management flexibility, whileminimizing yield reduction risk in the insured crop. In accordance withthe 2018 Farm Bill, for crops planted in the 2020 crop year and later,insurance attaches at time of planting the insured crop and any concernsregarding cover crop management practices will be applicable to RMAGood Farming Practice (GFP) determinations. This is consistent with allother production management decisions (e.g. fertilizer application,seeding rates, tillage practices etc.).","applicationInstructions":"All multi-peril crop insurance, including CAT policies, are available fromprivate crop insurance agents. A list of crop insurance agents is availableat all USDA service centers and on the RMA website on the AgentLocator (/Information-Tools/Agent-Locator) page .","resources":"","factSheet":"https://www.rma.usda.gov/sites/default/files/2024-02/Cover-Crops-and-Crop-Insurance-Fact-Sheet.pdf","programWebpage":"https://www.rma.usda.gov/about-crop-insurance/highlighted-initiatives-plans/cover-crops","organization":"Risk Management Agency"}},{"name":"Dairy Revenue Protection (DRP)","livestock":1,"annualCrops":0,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Crop & Livestock Insurance","droughtScore":0,"notes":"Revenue-based, not drought-specific","details":{"introduction":"Dairy Revenue Protection (Dairy-RP) isdesigned to insure against unexpecteddeclines in the quarterly revenue frommilk sales relative to a guaranteedcoverage level. The expected revenue isbased on futures prices for milk and dairycommodities, and the amount of coveredmilk production elected by the dairyproducer. The covered milk production isindexed to the state or region where thedairy producer is located.","eligibility":"Dairy-RP is available in all counties in all50 states.","terms":"Dairy-RP offers two Revenue pricing options:\n\n\u2022 The Class Pricing Option uses acombination of Class III and Class IVmilk prices as a basis for determiningcoverage and indemnities.\n\n\u2022 The Component Pricing Optionuses the component milk prices forbutterfat, protein and other solids asa basis for determining coverage andindemnities. Under this option you mayselect the butterfat test percentageand protein test percentage toestablish your insured milk price.\n\nYou may cover 80 percent to 95 percentof your expected quarterly revenue in fivepercent increments.A premium subsidy is available and is basedon the coverage level you selected.","applicationInstructions":"All multi-peril livestockinsurance, includingCatastrophic Risk Protectionpolicies, are available fromprivate insurance agents. Alist of livestock insuranceagents is available on theRMA website by using therma.usda.gov/tools-reports/agent-locator.","resources":"","factSheet":"https://www.rma.usda.gov/about-crop-insurance/fact-sheets/dairy-revenue-protection","programWebpage":"https://www.rma.usda.gov/about-crop-insurance/frequently-asked-questions/dairy-revenue-protection","organization":"Risk Management Agency"}},{"name":"Enhanced Coverage Option (ECO)","livestock":0,"annualCrops":1,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Crop & Livestock Insurance","droughtScore":0,"notes":"Area-based revenue coverage","details":{"introduction":"The Enhanced Coverage Option (ECO) is a new crop insurance option that provides additional area-based coverage for a portion of your underlying crop insurance policy deductible. It must be purchased as an endorsement to the Yield Protection, Revenue Protection, Revenue Protection with the Harvest Price Exclusion, Actual Production History or Yield Based Dollar Amount of Insurance policy. ECO offers producers a choice of 95% or 90% trigger levels. Trigger means the percentage of expected yield or revenue at which a loss becomes payable.","eligibility":"ECO is available for the crops below in most counties where these crops are grown. Additional crops will be added in subsequent years based on producer interest and data availability.","terms":"Federal law limits the authority for Federal Crop Insurance to insure individual farm yields at 85% coverage levels. If you need higher coverage levels for your farm, then ECO can offer coverage up to 95%, at a county level to enhance your total coverage. You should consult your crop insurance agent to determine what best meets your individual risk management needs.\n\nECO follows the coverage of your underlying policy. If you choose Yield Protection or a yield-based policy, then ECO covers yield loss. If you choose a Revenue Protection policy, then ECO covers revenue losses.\n\nThe amount of ECO coverage depends on the liability of your underlying policy. However, ECO differs from the underlying policy in how a loss payment is triggered. The underlying policy pays a loss on an individual basis and an indemnity is triggered when you have an individual loss in yield or revenue. ECO pays a loss on an area basis, and an indemnity is triggered when there is a decrease in the county level yield or revenue. ECO has two trigger levels: 90 and 95 percent. ECO provides a band of coverage between the elected trigger level and 86%. If the county yield or revenue is reduced beyond the trigger level you will receive an ECO indemnity. If the reduction in yield or revenue exceeds the 86% threshold, you will receive an indemnity equal to the full insured liability.","applicationInstructions":"All multi-peril crop insurance, including CAT policies, are available from private crop insurance agents. A list of crop insurance agents is available at all USDA service centers and on the RMA website at: www.rma.usda.gov/Information-Tools/Agent-Locator.","resources":"","factSheet":"https://old.rma.usda.gov/en/Fact-Sheets/National-Fact-Sheets/Enhanced-Coverage-Option","programWebpage":"","organization":"Risk Management Agency"}},{"name":"Livestock Gross Margin (LGM) for Cattle","livestock":1,"annualCrops":0,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Crop & Livestock Insurance","droughtScore":0,"notes":"Price/margin risk, not drought","details":{"introduction":"The Livestock Gross Margin for Cattle (LGM for Cattle) Insurance Policy provides protection against the loss of gross margin (market value of livestock minus feeder cattle and feed costs) on cattle. The indemnity at the end of the 11-month insurance period is the difference, if positive, between the gross margin guarantee and the actual gross margin. The LGM for Cattle Insurance Policy uses futures prices to determine the expected gross margin and the actual gross margin. Adjustments to futures prices are state- and month-specific basis levels. The price the producer receives at the local market is not used in these calculations.","eligibility":"Any producer who owns cattle in any of the 50 states is eligible for LGM for Cattle insurance coverage.\n\nOnly cattle sold for commercial or private slaughter primarily intended for human consumption and fed in any of the 50 states are eligible for coverage under the LGM for Cattle Insurance Policy. Cattle cannot be insured under more than one livestock policy issued under the Act.","terms":"LGM for Cattle has two key features:\n\nProducers can sign up for LGM for Cattle coverage each Thursday and insure all the cattle they expect to market over a rolling 11-month insurance period. The producer does not have to decide on the mix of options to purchase, the strike price of the options, or the date of entry.\n\nThe LGM for Cattle policy can be tailored to any size farm. Options cover fixed amounts of commodities and those amounts may be too large to be used in the risk management portfolio of some farms.","applicationInstructions":"All multi-peril crop insurance, including CAT policies, are available from private crop insurance agents. A list of crop insurance agents is available at all USDA service centers and on the RMA website at: www.rma.usda.gov/Information-Tools/Agent-Locator.","resources":"","factSheet":"https://www.rma.usda.gov/sites/default/files/2024-02/Livestock-Gross-Margin-Insurance-Cattle-Fact-Sheet.pdf","programWebpage":"https://www.rma.usda.gov/about-crop-insurance/frequently-asked-questions/livestock-gross-margin-cattle","organization":"Risk Management Agency"}},{"name":"Livestock Risk Protection (LRP) Feeder Cattle","livestock":1,"annualCrops":0,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Crop & Livestock Insurance","droughtScore":0,"notes":"Price risk only","details":{"introduction":"Feeder Cattle (LRP-Feeder Cattle) is designed to insure against declining market prices. You may choose from a variety of coverage levels and insurance periods that match the time your feeder cattle would normally be marketed (ownership may be retained).\n\nYou may buy LRP-Feeder Cattle insurance throughout the year from Risk Management Agency (RMA) approved livestock insurance agents. Premium rates, coverage prices, and actual ending values are posted online daily.\n\nYou may choose coverage prices ranging from 70 to 100 percent of the expected ending value. At the end of the insurance period, if the actual ending value is below the coverage price, you will be paid an indemnity for the difference between the coverage price and actual ending value.\n\nVisit RMA\u2019s website to see the LRP-Feeder Cattle program\u2019s coverage prices, rates, actual ending values, and per hundredweight insurance cost (see useful links). Actual ending values are based on weighted average prices, from the Chicago Mercantile Exchange Group Feeder Cattle Index. Actual ending values are posted on RMA\u2019s website at the end of the insurance period.","eligibility":"Any producer who owns cattle in any of the 50 states is eligible.","terms":"You submit a one-time application for LRP-Feeder Cattle coverage. After the application is accepted, you can buy specific coverage endorsements throughout the year for up to 12,000 head of feeder cattle that are expected to weigh up to 1000 pounds at the end of the insurance period. The annual limit for LRP-Feeder Cattle is 25,000 head per producer per year (July 1 to June 30).\n\nThe length of insurance coverage available for each specific coverage endorsement is 13, 17, 21, 26, 30, 34, 39, 43, 47, or 52 weeks.\n\nCoverage is available for:\nCalves;\nSteers;\nHeifers;\nPredominantly Brahman cattle;\nPredominantly dairy cattle; and\nUnborn calves.\n\nYou may also choose from two weight ranges - 100-599 pounds and 600-1000 pounds. LRP-Feeder Cattle insurance is available in all counties in all states.","applicationInstructions":"You must buy LRP-Feeder Cattle insurance through a livestock insurance agent. You may fill out an application at any time. However, insurance does not attach until you buy a specific coverage endorsement. You may buy multiple specific coverage endorsements with one application. Your insurance coverage starts the day you buy a specific coverage endorsement and RMA approves the purchase.","resources":"Daily LRP Coverage Prices, Rates, and Actual Ending Values:\nrma.usda.gov/Information-Tools/Livestock-Reports\n\nPremium Calculator:\newebapp.rma.usda.gov/apps/costestimator/\n\nApproved livestock agents and insurance companies:\nrma.usda.gov/Information-Tools/Agent-Locator\n\nRelated AMS online livestock reports:\nmarketnews.usda.gov","factSheet":"https://old.rma.usda.gov/en/Fact-Sheets/National-Fact-Sheets/Livestock-Risk-Protection-Feeder-Cattle","programWebpage":"","organization":"Risk Management Agency"}},{"name":"Multiple Peril Crop Insurance (MPCI)","livestock":0,"annualCrops":1,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Crop & Livestock Insurance","droughtScore":2,"notes":"Covers yield losses including drought","details":{"introduction":"Multi-Peril Crop Insurance (MPCI) is a commonform of crop insurance that can work for bothconventional and organic farms and ranches.Generally, MPCI is used to cover losses fromnatural disasters, crop loss, and market pricechanges. The coverage can work as revenue protection or yield protection and covers a variety of crops.","eligibility":"","terms":"MPCI insures a percentage of historical cropproduction to protect farmers from yield loss\nAPH refers to a farmer's history of acres plantedand crops produced over a 5-10 year period\nBoth revenue protection and yield protectionrequire the farmer to choose a coverage levelthat ranges from 50-85%\nPremium paid by the farmer is lower for lowerlevels of coverage, allowing for risk adjustmentbased on your needs.\nThe coverage level tells you how much revenuewill be insured based on the expected fall orspring contract prices and Actual ProductionHistory (APH)\nInsurance companies multiply the APH by thecoverage level to calculate the guarantee(Guarantee = APH x coverage level)\nIf the production level is below this guarantee,and you have an approved loss, you may beeligible for an indemnity payment.","applicationInstructions":"All multi-peril crop insurance, including CAT policies, are available from private crop insurance agents. A list of crop insurance agents is available at all USDA service centers and on the RMA website at: www.rma.usda.gov/Information-Tools/Agent-Locator.","resources":"","factSheet":"https://organicfarmersassociation.org/wp-content/uploads/2025/07/Crop-Ins-Factsheet-MPCI.pdf","programWebpage":"https://www.rma.usda.gov/taxonomy/term/274","organization":"Risk Management Agency"}},{"name":"Nursery Value Select Coverage","livestock":0,"annualCrops":0,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":1,"mixedOperations":0,"supportType":"Crop & Livestock Insurance","droughtScore":1,"notes":"Covers plant loss, including drought impacts","details":{"introduction":"Nursery Value Select (NVS) is an inventory-based pilot program that allows nurseryproducers to select the dollar amountof coverage that best fits their riskmanagement needs.","eligibility":"NVS is available in all states and counties.\n\nIn order to be eligible for NVS coverage, you must be a wholesale nursery that derives at least 40 percent of its gross income from the wholesale marketing of plants to:\n\nRetailers who resell to end users;\nLandscape contractors;\nGovernment entities or organizations; and/or\nCommercial fruit producers.\n\nYou must also have a wholesale catalog that is provided to customers and used in the sale of the plants.","terms":"For insurance to attach on the start date of the crop year, all documentation must be submitted on or before the sales closing date.\n\nFor insurance to attach on the start date of the crop year, all documentation must be submitted on or before the sales closing date. If you\u2019re applying for coverage or renewing coverage after the sales closing date:\nInsurance does not attach until the 31st day (30-day waiting period) after acceptable documents are filed; and\nPremium is owed from the first day of the month insurance attaches.","applicationInstructions":"NVS is available for purchase from your local crop insurance agent. You can find a crop insurance agent at the Agent Locator link on the Risk Management Agency (RMA) website.\n\nThese agents work for insurance companies that have reinsurance agreements with the RMA.\n\nYou must submit the following:\n\nCrop insurance application;\n\nNursery Value Report (NVR) for each insured practice (field grown and/or container grown).\nThe NVR is a document that represents your declaration of the insurance choices you elect.\n\nMonthly Unit Value Report (MUVP) for each insured basic unit.\nThe MUVP is a document that represents your declaration for each basic unit by:\nMonth, from the first month to the last month of the insurance period; and\nThe maximum value of all specific plants in each insured plant category that you expect to have in your nursery (during each month of the insurance period).\n\nSubmit two printed copies or one electronic copy of the most recent catalog or price list, by season or plant category, if appropriate.\nAll documents must be acceptable and must be submitted on or before the sales closing date for insurance to attach on the first day of the insurance period.","resources":"","factSheet":"https://www.rma.usda.gov/about-crop-insurance/fact-sheets/nursery-value-select","programWebpage":"https://www.rma.usda.gov/about-crop-insurance/frequently-asked-questions/nursery-value-select","organization":"Risk Management Agency"}},{"name":"Pasture-Rangeland-Forage (PRF) Insurance","livestock":1,"annualCrops":0,"specialtyCrops":0,"forageHayPasture":1,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Crop & Livestock Insurance","droughtScore":2,"notes":"Directly tied to rainfall/drought index","details":{"introduction":"The PRF policy is an area-based insurance plan that covers perennial pasture, rangeland, or forage used to feed livestock. It provides producers a risk management tool to cover the precipitation needed to produce forage for their operation.\n\nArea-based means payments are not based on an individual producer's experience; rather, payments are based on a grid\u2019s deviation from normal experience. For example, under the Rainfall Index, if your ranch received a surplus of rain, but the area in your grid was below average, you could receive a payment or vice versa.","eligibility":"RI-PRF is being offered in all 48 contiguous states. The expansion for the 2017 crop year covered over 650 million haying and grazing acres. All counties within those 48 states were offered RI-PRF. A few producers did not have coverage because the majority of their grid crossed over either the northern or southern United States borders.","terms":"Producers must choose at least two, 2-month periods when precipitation is important for forage growth for their operation. These periods are called index intervals. RMA uses NOAA CPC data to calculate normal precipitation and deviations from normal precipitation. RMA uses NOAA precipitation data based on the Optimal Interpolation methodology. Interpolation is based on the idea that things closer together in space are generally more similar than those farther apart and it estimates precipitation for a grid using reporting stations within a search radius around the grid. More information about the technology and how NOAA CPC interpolates weather data to a specific grid can be found on RMA\u2019s PRF web page. Select \u201cRainfall Index, Pasture, Rangeland, Forage Technology\u201d. It is important to understand that precipitation is interpolated to the grid, not measured within the grid.","applicationInstructions":"Contact a crop insuranceagent to see how Federalcrop insurance can meetthe specific needs of youroperation. Crop insuranceis sold and delivered solelythrough private cropinsurance agents. A listof crop insurance agentsis available online at rma.usda.gov/agent-locator.","resources":"","factSheet":"https://www.rma.usda.gov/sites/default/files/2024-02/Pasture-Rangeland-Forage-Pilot-Insurance-Program-Fact-Sheet.pdf","programWebpage":"https://www.rma.usda.gov/about-crop-insurance/frequently-asked-questions/pasture-rangeland-forage","organization":"Risk Management Agency"}},{"name":"Supplemental Coverage Option (SCO)","livestock":0,"annualCrops":1,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Crop & Livestock Insurance","droughtScore":0,"notes":"Area yield/revenue, not drought-specific","details":{"introduction":"The Supplemental Coverage Option (SCO) is a crop insurance option that provides additional coverage for a portion of your underlying crop insurance policy deductible. You must buy it as an endorsement to the Yield Protection, Revenue Protection, or Revenue Protection with the Harvest Price Exclusion policy or to the Actual Production History policy for crops that don\u2019t have revenue protection available. The Federal Government pays 65 percent of the premium cost for SCO.","eligibility":"You choose SCO as an endorsement to the underlying policy. You must make this choice by the sales closing date for your underlying policy, and with the same insurance company. Any crop on a farm that you elected to participate in the Agriculture Risk Coverage (ARC) program (a program started in the 2014 Farm Bill, administered by the Farm Service Agency) is not eligible for SCO coverage.\n\nSCO was first available for the 2015 crop year in select counties for spring barley, corn, soybeans, wheat, sorghum, cotton, and rice. RMA will be making greater use of crop insurance data to expand SCO coverage into more areas, more crops, and to make SCO coverage more practice-specific (for example, irrigated in comparison to non-irrigated). Tools are available on RMA\u2019s public website to view availability and other program-related information. A map of SCO availability can be accessed through the Map Viewer tool on the RMA website at\npublic-rma.fpac.usda.gov/apps/MapViewer/index.html","terms":"SCO follows the coverage of your underlying policy. If you choose Yield Protection, then SCO covers yield loss. If you choose Revenue Protection, then SCO covers revenue loss.\n\nThe amount of SCO coverage depends on the liability, coverage level, and approved yield for your underlying policy. However, SCO differs from the underlying policy in how a loss payment is triggered. The underlying policy pays a loss on an individual basis and an indemnity is triggered when you have an individual loss in yield or revenue. SCO pays a loss on an area basis, and an indemnity is triggered when there is a county level loss in yield or revenue.","applicationInstructions":" All multi-peril crop insurance, including Catastrophic Risk Protection and SCO policies, are available from private crop insurance agents. A list of crop insurance agents is available at all USDA service centers and on the RMA website at www.rma.usda.gov/Information-Tools/Agent-Locator.","resources":"","factSheet":"https://old.rma.usda.gov/en/Fact-Sheets/National-Fact-Sheets/Supplemental-Coverage-Option","programWebpage":"","organization":"Risk Management Agency"}},{"name":"Whole Farm Revenue Protection (WFRP)","livestock":0,"annualCrops":0,"specialtyCrops":1,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":1,"mixedOperations":1,"supportType":"Crop & Livestock Insurance","droughtScore":0,"notes":"Revenue protection across multiple farm products; not specifically tied to drought conditions","details":{"introduction":"Whole-Farm Revenue Protection (WFRP) provides a risk management safety net for all commodities on the farm under one insurance policy and is available in all counties nationwide. This insurance plan is tailored for any farm with up to $17 million in insured revenue, including farms with specialty or organic commodities (both crops and livestock), or those marketing to local, regional, farm-identity preserved, specialty, or direct markets.","eligibility":"WFRP is available in all counties in all50 states.\n\nEligibility for WFRP coverage requires the producer to:\n\n\u2022 Be eligible to receive Federal benefits;\n\u2022 Be a U.S. citizen or resident;\n\u2022 File either a Schedule F tax form or other farm tax form that canbe converted to a Substitute Schedule F for a specified number ofyears (see \u201cInformation You Provide\u201d below);\n\u2022 Have no more than $17 million in insured revenue, which is thefarm revenue allowed to be insured under the policy multiplied bythe coverage level you select (see table above);\u2022 Coverage of expected revenue from animals and animalproducts, excluding aquaculture commodities, is limited to$2 million;\u2022 Coverage of expected revenue from greenhouse andnursery, excluding aquaculture commodities, is limited to$2 million;\n\u2022 Have no more than 50 percent of total revenue from commoditiespurchased for resale;\n\u2022 Meet the diversification requirements of the policy by having twoor more commodities if a commodity you are raising has revenueprotection under the Common Crop Insurance Policy available; and\n\u2022 Meet the diversification requirements of the policy by having twoor more commodities if there are potatoes on the farm","terms":"Coverage is provided for the duration of the producer\u2019s tax year (theinsurance period). The insurance period is a calendar year if taxes are filedby calendar year, or a fiscal year if taxes are filed by fiscal year.\n\nRevenue Losses - You must submit a notice of loss within 72 hours afterdiscovery that revenue for the policy year could be below the insuredrevenue. Inspections may be required for losses. You must have filed farmtaxes for the policy year before any claim can be made. You must makeclaims no later than 60 days after the date you submit farm tax forms tothe Internal Revenue Service (IRS). Claim payments for a revenue lossunder WFRP are paid within 30 days after the determination of a paymentdue as long as you are in compliance with the policy.","applicationInstructions":"All multi-peril crop insurance, including CAT policies, are available from private crop insurance agents. A list of crop insurance agents is available at all USDA service centers and on the RMA website at www.rma.usda.gov/Information-Tools/Agent-Locator-Page.","resources":"","factSheet":"https://www.rma.usda.gov/sites/default/files/2024-02/Whole-Farm-Revenue-Protection-Fact-Sheet.pdf","programWebpage":"https://www.rma.usda.gov/policy-procedure/general-policies/whole-farm-revenue-protection","organization":"Risk Management Agency"}},{"name":"Agriculture Risk Coverage and Price Loss Coverage Programs (ARC/PLC)","livestock":0,"annualCrops":1,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Disaster Assistance","droughtScore":0,"notes":"Price/income support","details":{"introduction":"The Agriculture Risk Coverage (ARC) and Price Loss Coverage (PLC) programs, administered by the Farm Service Agency (FSA), offer financial assistance to agricultural producers. The ARC program provides payments when the actual revenue for a farm is less than a guarantee set based on historical data and market conditions. The PLC program provides payments when the effective price for a covered commodity falls below its effective reference price. These programs aim to protect farmers from significant income losses due to fluctuations in crop prices or revenue shortfalls.\n\nBenefits\n\nProvides financial support during periods of low prices or revenue shortfalls.\nHelps stabilize income for farmers and ranchers.\nOffers a safety net against market volatility.\n \nAdditional Benefits\n\nFinancial Stability: Offers a safety net to manage price and revenue risks.\nIncome Support: Helps maintain farm income stability during economic downturns.\nFlexibility: Producers can choose between ARC and PLC based on their individual needs and commodity markets.","eligibility":"Eligible participants include agricultural producers who have an interest in a commodity grown on a farm with base acres.","terms":"Covered Commodities\n\n22 covered commodities including wheat, oats, barley, corn, grain sorghum, long grain rice, medium/short grain rice, temperate japonica rice, seed cotton, dry peas, lentils, large and small chickpeas soybeans, peanuts, sunflower seed, canola, flaxseed, mustard seed, rapeseed, safflower, crambe, and sesame seed.\n\nProgram-specific reference prices and revenue guarantees.\n\nPayment Triggers\n\nARC payments are triggered when actual revenue falls below the guaranteed level.\n\nPLC payments are triggered when market year average prices fall below the effective reference price.","applicationInstructions":"To enroll in the ARC or PLC programs, agricultural producers can contact their local FSA office or apply for ARC and PLC online. ","resources":"","factSheet":"https://www.fsa.usda.gov/sites/default/files/2025-09/FSA_ARC%20%26%20PLC_3pg_Fact%20Sheet-SEPT%202025_final.pdf","programWebpage":"https://www.fsa.usda.gov/resources/programs/arc-plc","organization":"Farm Service Agency"}},{"name":"Dairy Margin Coverage Program (DMC)","livestock":1,"annualCrops":0,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Disaster Assistance","droughtScore":0,"notes":"Milk margin, not drought","details":{"introduction":"The Dairy Margin Coverage (DMC) Program, administered by the Farm Service Agency (FSA), is a voluntary risk management tool for dairy producers. It offers financial assistance when the margin between the all-milk price and average feed cost falls below a coverage level chosen by the producer.  \n\nBy participating in DMC, dairy farmers can protect themselves against declines in milk prices and increases in feed costs, thereby ensuring more predictable and stable income. The program includes both catastrophic coverage and additional, higher levels of coverage for an annual premium. \n\nAdditional Benefits \n\nRisk Management: Helps dairy producers manage the financial risks associated with volatile milk prices and feed costs. \n\nIncome Stabilization: Provides a safety net, ensuring more stable and predictable income for dairy farmers. \n\nCustomizable Coverage: Offers flexibility for producers to choose coverage levels that best fit their individual risk management needs. ","eligibility":"Eligible applicants include dairy operations in the United States that produce and commercially market milk from cows. Producers must provide production records and be in compliance with conservation regulations.\u00a0","terms":"Program Features \n\nCoverage Levels: Producers can select coverage levels ranging from $4.00 to $9.50 per hundredweight (cwt) of milk, in $0.50 increments. \n\nPremium Rates: Vary based on the coverage level and the production history of the dairy operation. Discounts are available for small-scale producers and those opting for higher coverage levels. \n\nProduction History: Based on the highest milk production in any one of the previous three years for a dairy operation commercially, marketing milk prior to 2014 or recent annual milk production for a new dairy operation. \n\nPayments: Calculated monthly when the actual dairy production margin falls below the selected coverage level. Payments help offset the difference between the margin and the selected coverage level.   ","applicationInstructions":"To enroll in the Dairy Margin Coverage Program, dairy producers must complete and submit an application to their local FSA office during the specified enrollment period. The application process includes providing production records and selecting the desired coverage level. Detailed enrollment instructions and deadlines are available through the local FSA office.\u00a0","resources":"","factSheet":"https://www.fsa.usda.gov/sites/default/files/documents/dairy_margin_coverage_program_2022_fact_sheet.pdf","programWebpage":"https://www.fsa.usda.gov/resources/programs/dairy-margin-coverage-program-dmc","organization":"Farm Service Agency"}},{"name":"Emergency Assistance for Livestock, Honey Bees, and Farm-Raised Fish (ELAP)","livestock":1,"annualCrops":0,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Disaster Assistance","droughtScore":2,"notes":"Covers drought-related feed/water losses","details":{"introduction":"The Emergency Assistance for Livestock, Honey Bees, and Farm-Raised Fish Program (ELAP), administered by the Farm Service Agency (FSA), offers financial aid to producers who suffer losses from specific adverse conditions not covered by other USDA disaster assistance programs. This includes losses due to disease, certain adverse weather events, and other qualifying conditions affecting livestock, honey bees, and farm-raised fish. ELAP provides critical support to help producers recover and sustain their operations.","eligibility":"Eligible applicants include producers of livestock, honey bees, and farm-raised fish who have suffered losses due to disease, adverse weather, or other qualifying conditions. Producers must provide verifiable documentation of the losses and meet all program requirements.\n","terms":"Covered Losses\nLivestock losses due to eligible disease, certain adverse weather, and feed and water shortages.\nHoney bee colony, hive, and feed losses due to colony collapse disorder, eligible adverse weather, and other conditions.\nFarm-raised fish death losses due to eligible disease, adverse weather, and other qualifying conditions.\n \nPayment Rates: Payments are based on a percentage of the fair market value of the livestock, honey bees, or fish lost, as well as the cost of feed and water shortages. Specific rates are detailed in program guidelines.\n \nDocumentation Requirements: Producers must provide verifiable documentation of losses and the conditions causing the losses. This may include veterinary records, feed and water receipts, purchase records, and other supporting documents.","applicationInstructions":"To apply for the Emergency Assistance for Livestock, Honey Bees, and Farm-Raised Fish Program, producers must complete and submit a notice of loss and an application for payment to their local FSA office. The process includes providing documentation of the losses and the conditions causing the losses. Detailed enrollment instructions and deadlines are available through the local FSA office.","resources":"","factSheet":"https://www.fsa.usda.gov/tools/informational/fact-sheets/emergency-assistance-livestock-honeybees-farm-raised-fish-program-4","programWebpage":"https://www.fsa.usda.gov/resources/programs/emergency-assistance-livestock-honeybees-farm-raised-fish-elap","organization":"Farm Service Agency"}},{"name":"Emergency Commodity Assistance Program (ECAP)","livestock":0,"annualCrops":1,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Disaster Assistance","droughtScore":1,"notes":"Provides general emergency support for crops; may include drought impacts but is not drought-specific","details":{}},{"name":"Emergency Conservation Program (ECP)","livestock":1,"annualCrops":1,"specialtyCrops":1,"forageHayPasture":1,"forestry":0,"irrigatedPerennial":0,"mixedOperations":1,"supportType":"Disaster Assistance","droughtScore":2,"notes":"Land recovery after drought damage","details":{"introduction":"The Emergency Conservation Program (ECP), administered by the Farm Service Agency (FSA), offers financial and technical assistance to agricultural producers to repair and restore farmland affected by natural disasters such as floods, hurricanes, wildfires, drought, and other calamities. ECP helps farmers and ranchers implement emergency conservation measures to rehabilitate damaged land, restore agricultural production, and prevent further environmental degradation.","eligibility":"Eligible applicants include farmers and ranchers who have suffered damage to their farmland due to natural disasters. The damage must significantly impair the land\u2019s agricultural productivity or pose a threat to land or water resources.\n\nAdditional ECP Benefits\nQuick Response: ECP provides prompt assistance to address immediate conservation needs following a disaster, helping producers quickly restore their operations.\n\nEnvironmental Protection: By addressing disaster-related damage, ECP helps prevent further environmental degradation and promotes the long-term sustainability of agricultural land.\n\nEconomic Stability: ECP helps producers recover from the financial impact of natural disasters, supporting the economic stability of rural communities.","terms":"Program Features:\n\nCovered Practices\nRemoving debris from farmland.\nGrading, shaping, or leveling land.\nRestoring permanent fences.\nRestoring conservation structures.\nImplementing emergency water conservation measures during severe drought.\n\nPayment Rates: ECP provides cost-share assistance of up to 75% of the cost of approved conservation practices. Limited resource producers may be eligible for up to 90% cost-share.\n\nFunding: The availability of ECP funds is subject to annual appropriations and is provided on a first-come, first-served basis. Funding priorities may be established based on the severity of the disaster and the extent of the damage.","applicationInstructions":"To apply for the Emergency Conservation Program, producers must submit a request for assistance to their local FSA office. The application process includes an assessment of the damage, documentation of the disaster impact, and a description of the proposed conservation measures. Detailed enrollment instructions and deadlines are available through the local FSA office.","resources":"","factSheet":"https://www.fsa.usda.gov/tools/informational/fact-sheets/emergency-conservation-program-ecp","programWebpage":"https://www.fsa.usda.gov/resources/programs/emergency-conservation-program-ecp","organization":"Farm Service Agency"}},{"name":"Emergency Forest Restoration Program (EFRP)","livestock":0,"annualCrops":0,"specialtyCrops":0,"forageHayPasture":0,"forestry":1,"irrigatedPerennial":0,"mixedOperations":1,"supportType":"Disaster Assistance","droughtScore":1,"notes":"Forest recovery; may include drought damage","details":{"introduction":"The Emergency Forest Restoration Program (EFRP) helps the owners of non-industrial private forests restore forest health damaged by natural disasters. The EFRP does this by authorizing payments to owners of private forests to restore disaster damaged forests.\n\nThe local FSA County Committee implements EFRP for all disasters with the exceptions of drought and insect infestations. In the case of drought or an insect infestation, the national FSA office authorizes EFRP implementation.\n\nForests provide shelter for wildlife, help provide nutrients for soil, and help protect water supplies. By restoring forests and forest health the EFRP works to protect natural resources and wildlife habitats.","eligibility":"Is My Forest Eligible?\nThe FSA County Committee inspects the damage to determine if forest land is eligible for EFRP. For land to qualify for EFRP funds, the damage from the natural disaster must create new conservation problems that if not dealt with would:\n\nHarm the natural resources on the land\nSignificantly affect future land use\n\nOnly owners of nonindustrial private forests with tree cover existing before the natural disaster occurred are eligible to apply. The land must be owned by a private individual, group, association, corporation or other private legal entity that has decision making authority on the land and doesn\u2019t use the land for business purposes.","terms":"Funding for EFRP is determined by Congress. Up to 75% of the cost to implement emergency conservation practices can be provided, however the final amount is determined by the committee reviewing the application. The FSA County Committee is able to approve applications up to $125,000 while $125,001 to $250,000 requires state committee approval. Amounts over $250,000 require the approval of the national FSA office. Additionally, a limit on payments of $500,000 per person or entity per disaster applies.","applicationInstructions":"Owners should check with their\u00a0local FSA office\u00a0to find out about EFRP sign-up periods after a natural disaster has occurred.","resources":"","factSheet":"https://www.fsa.usda.gov/tools/informational/fact-sheets/emergency-forest-restoration-program-efrp","programWebpage":"https://www.fsa.usda.gov/resources/disaster-assistance-program/emergency-forest-restoration","organization":"Farm Service Agency"}},{"name":"Emergency Watershed Protection Program (EWP)","livestock":1,"annualCrops":1,"specialtyCrops":1,"forageHayPasture":1,"forestry":0,"irrigatedPerennial":0,"mixedOperations":1,"supportType":"Disaster Assistance","droughtScore":1,"notes":"Watershed repair; more flood-focused but relevant","details":{"introduction":"The EWP Program offers technical and financial assistance to help local communities relieve imminent threats to life and property caused by floods, fires, windstorms and other natural disasters that impair a watershed. EWP does not require a disaster declaration by federal or state government officials for program assistance to begin. The NRCS State Conservationist can declare a local watershed emergency and initiate EWP program assistance in cooperation with an eligible sponsor (see the Eligibility section below). NRCS will not provide funding for activities undertaken by a sponsor prior to the signing of a cooperative agreement between NRCS and the sponsor.\n\nNRCS offers financial and technical assistance for various activities under the EWP Program, including: \n\nRemove debris from stream channels, road culverts and bridges;\nreshape and protect eroded streambanks;\ncorrect damaged or destroyed drainage facilities;\nestablish vegetative cover on critically eroding lands;\nrepair levees and structures;       \nrepair certain conservation practices, and\npurchase of EWP Buyouts.","eligibility":"Recovery Projects\nRecovery projects begin with a local sponsor or legal subdivision of state or tribal government. Eligible sponsors include cities, counties, towns, conservation districts, or any federally-recognized Native American tribe or tribal organization. Interested public and private landowners must work through a sponsor.\n\nEWP BUYOUT Option\nIn some situations, landowners can directly apply for assistance through a floodplain easement at the local NRCS office when project funding for floodplain easements becomes available. States will hold a signup period for the impacted communities and the local NRCS offices will publicize that information in the affected communities.\n\nThe EWP Program cannot be used:\nto address the same structural issue or practice 3 times within 10 years;\nfor existing operation and maintenance;\nto repair, rebuild, or maintain any transportation facilities, utilities, or similar facilities;\nto restore projects installed by another federal agency;\nto repair nonstructural management practices;\nto repair coastal erosions to beaches, dunes, and shorelines, including those along the Great Lakes;\nif the recovery measures are eligible for the Emergency Conservation Program offered thru the Farm Service Agency (FSA).","terms":"All EWP projects must have a sponsor and\u2004demonstrate that they reduce threats to life and property; be economically, environmentally and socially sound; and must be designed to acceptable engineering standards.\n\nNRCS partners with diverse sponsors to complete EWP Program projects. Sponsors include cities, counties, towns, conservation districts, or any federally-recognized Native American tribe or tribal organization.\n\nSponsors can apply for EWP Program assistance directly to NRCS while public and private landowners can apply for this assistance through a local sponsor.\n\nCheck out the EWP Sponsor Resource page(https://www.nrcs.usda.gov/resources/guides-and-instructions/ewp-sponsor-resources) for more information.","applicationInstructions":"https://www.nrcs.usda.gov/programs-initiatives/emergency-watershed-protection/emergency-watershed-program-state-contacts","resources":"","factSheet":"https://www.nrcs.usda.gov/sites/default/files/2022-08/NRCS_EWPP_Fact%20Sheet-2021.pdf","programWebpage":"https://www.nrcs.usda.gov/programs-initiatives/emergency-watershed-protection","organization":"Natural Resources Conservation Service"}},{"name":"Livestock Forage Disaster Program (LFP)","livestock":1,"annualCrops":0,"specialtyCrops":0,"forageHayPasture":1,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Disaster Assistance","droughtScore":2,"notes":"Explicit drought forage loss program","details":{"introduction":"The Livestock Forage Disaster Program (LFP), administered by the Farm Service Agency (FSA), offers financial support to livestock producers who experience grazing losses due to qualifying drought conditions or fire on federally managed rangelands. The program is designed to help producers recover from significant forage losses, ensuring the continuity of their operations and the well-being of their livestock. LFP provides payments to eligible producers to compensate for lost grazing opportunities and to help cover additional feed costs incurred due to the disaster.","eligibility":"Eligible applicants include livestock producers who own or lease grazing land or pastureland in areas affected by drought or fire. Producers must provide verifiable documentation of grazing losses and meet all program requirements.\n\nAdditional Benefits\nFinancial Relief: Provides critical financial assistance to help producers cover additional feed costs and mitigate the economic impact of forage losses.\nRisk Management: Supports the resilience of livestock operations by helping producers manage the risks associated with natural disasters.\nContinuity of Operations: Ensures that livestock producers can continue their operations despite significant forage losses, promoting the stability of the agricultural sector.","terms":"Eligible Livestock: Includes beef cattle, dairy cattle, buffalo, beefalo, equine, goats, sheep, alpacas, ostriches, emus. deer, elk, reindeer, and llamas that are maintained for commercial use as part of a farming operation.\n\nPayment Rates: Payments are calculated based on the severity of the drought (as determined by the U.S. Drought Monitor) and the number of livestock units. For fire losses, payments are calculated based on the number of eligible livestock and the number of grazing days lost due to fire.\n\nGrazing Losses: LFP compensates for grazing losses due to:\nDrought: Compensates for losses on privately owned or cash-leased land when the county is designated as experiencing drought conditions.\nFire: Compensates for losses on federally managed rangeland if the producer is prohibited from grazing the normal permitted livestock due to fire.","applicationInstructions":"To apply for the Livestock Forage Disaster Program, producers must submit an application to their local FSA office. The application process includes providing documentation of grazing losses, details of the disaster impact, and information about the eligible livestock. Detailed enrollment instructions and deadlines are available through the local FSA office.","resources":"https://www.fsa.usda.gov/programs-and-services/disaster-assistance-program/livestock-forage/index","factSheet":"https://www.fsa.usda.gov/tools/informational/fact-sheets/livestock-forage-disaster-program-lfp","programWebpage":"https://www.fsa.usda.gov/resources/programs/livestock-forage-disaster-program-lfp","organization":"Farm Service Agency"}},{"name":"Livestock Indemnity Program (LIP)","livestock":1,"annualCrops":0,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Disaster Assistance","droughtScore":1,"notes":"Drought can lead to eligible losses (livestock death), but drought itself is not the program trigger.","details":{"introduction":"The Livestock Indemnity Program (LIP), administered by the Farm Service Agency (FSA), offers financial compensation to livestock owners and contract growers who suffer significant livestock losses beyond normal mortality levels due to eligible adverse events. These events include adverse weather conditions, diseases, and attacks by federally protected animals. LIP helps mitigate the financial impact of these losses, enabling producers to recover and continue their operations.\n\nAdditional LIP Benefits\nFinancial Relief: LIP provides crucial financial assistance to livestock producers facing significant losses, helping them recover from unexpected adverse events.\nEconomic Stability: By compensating for excessive livestock losses, LIP supports the economic stability of livestock operations and rural communities.\nRisk Management: LIP is part of a broader suite of USDA disaster assistance programs designed to help producers manage risk and ensure the continuity of agricultural production.","eligibility":"Eligible applicants include livestock owners and contract growers who have experienced livestock deaths in excess of normal mortality due to adverse weather, disease, or attacks by federally protected animals. Applicants must provide verifiable documentation of the losses and meet all program requirements.","terms":"Compensation Rates: Payments are calculated based on 75% of the fair market value of the livestock on the day before the death occurred. Specific rates are set for different categories of livestock.\n\nDocumentation Requirements: Applicants must provide verifiable documentation of livestock deaths and the circumstances causing the losses. This may include veterinary records, purchase records, and other supporting documents.","applicationInstructions":"To apply for the Livestock Indemnity Program, producers must complete and submit a notice of loss and an application for payment to their local FSA office. The process includes providing documentation of the livestock losses and the eligible adverse events that caused the losses. Detailed enrollment instructions and deadlines are available through the local FSA office.","resources":"https://www.farmraise.com/usda-fsa/lip-decision-tool","factSheet":"https://www.fsa.usda.gov/tools/informational/fact-sheets/livestock-indemnity-program-lip","programWebpage":"https://www.fsa.usda.gov/resources/programs/livestock-indemnity-program-lip","organization":"Farm Service Agency"}},{"name":"Noninsured Crop Disaster Assistance Program (NAP)","livestock":0,"annualCrops":1,"specialtyCrops":1,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Disaster Assistance","droughtScore":2,"notes":"Covers drought losses for noninsured crops","details":{"introduction":"The Noninsured Disaster Assistance Program (NAP) offers financial support to producers of non-insurable crops to protect against natural disasters that result in lower yields, destroyed crops, or the inability to plant. NAP provides coverage equivalent to catastrophic (CAT) and additional (buy-up) levels of risk protection, helping producers manage risk and maintain their operations during and after adverse conditions.","eligibility":"Eligible crops include those for which federal crop insurance is not available, such as fruits, vegetables, aquaculture, floriculture, mushrooms, turfgrass, ginseng, honey, maple sap, and others. Producers must meet specific criteria and comply with all program requirements. Producers are encouraged to check with their local FSA office for specific requirements, application deadlines, and additional program details.","terms":"Coverage Levels\n\nCatastrophic Coverage (CAT): Provides coverage at 50% of the approved yield and 55% of the average market price.\nBuy-Up Coverage: Offers higher levels of coverage, up to 65% of the approved yield and 100% of the average market price.\nApplication Deadline: Producers must apply for coverage by the crop-specific application closing date.\n\nService Fee: Producers must pay a service fee of $325 per crop per county, not to exceed $825 per producer per county or $1,950 for multi-county producers.\n\nPremiums: For buy-up coverage, additional premiums apply based on the coverage level selected.\n","applicationInstructions":"To apply for NAP coverage, producers must submit an application for coverage and service fee by the application closing date for their specific crops. In the event of a loss, producers must also file a notice of loss and an application for payment. Detailed enrollment instructions and deadlines are available through the local Farm Service Agency (FSA) office.","resources":"https://www.fsa.usda.gov/resources/programs/noninsured-crop-disaster-assistance-related-information","factSheet":"https://www.fsa.usda.gov/tools/informational/fact-sheets/noninsured-crop-disaster-assistance-program-nap","programWebpage":"https://www.fsa.usda.gov/resources/programs/noninsured-disaster-assistance-program-nap","organization":"Farm Service Agency"}},{"name":"Tree Assistance Program (TAP)","livestock":0,"annualCrops":0,"specialtyCrops":1,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":1,"mixedOperations":0,"supportType":"Disaster Assistance","droughtScore":2,"notes":"Covers drought losses for noninsured crops","details":{"introduction":"The Tree Assistance Program (TAP), administered by the Farm Service Agency (FSA), offers financial support to orchardists and nursery tree growers who experience losses due to natural disasters. TAP helps cover the cost of replanting or rehabilitating eligible trees, bushes, and vines that produce annual crops and have been damaged or destroyed. This program is crucial for helping producers recover from adverse events and ensuring the long-term viability of their agricultural operations.","eligibility":"Eligible applicants include orchardists and nursery tree growers who produce annual crops for commercial purposes and have suffered losses due to natural disasters. Applicants must provide verifiable documentation of the losses and meet all program requirements.","terms":"Covered Losses\n\nReplanting or rehabilitating trees, bushes, and vines that have been damaged or destroyed by natural disasters.\nEligible plantings must have suffered more than a 15% mortality rate (adjusted for normal mortality) to qualify for assistance.\n\nPayment Rates: TAP provides cost-share assistance of up to 65% of the actual cost of replanting or rehabilitating damaged or destroyed trees, bushes, and vines. Limited resource, socially disadvantaged, and beginning farmers or ranchers may be eligible for up to 75% cost-share.\n","applicationInstructions":"To apply, contact your local USDA service center.\n\nApplications must be submitted either the later of 60 calendar days after (date of publication in FR) or within 90 calendar days of:\n\nthe disaster event; or\n\nthe date when the loss is apparent to the producer.","resources":"","factSheet":"https://www.fsa.usda.gov/tools/informational/fact-sheets/tree-assistance-program-tap","programWebpage":"https://www.fsa.usda.gov/resources/programs/tree-assistance-program-tap","organization":"Farm Service Agency"}},{"name":"Emergency Farm Loans","livestock":1,"annualCrops":1,"specialtyCrops":1,"forageHayPasture":1,"forestry":0,"irrigatedPerennial":0,"mixedOperations":1,"supportType":"Disaster Assistance / Loans","droughtScore":2,"notes":"Available after drought disasters","details":{"introduction":"Emergency Farm Loans, administered by the Farm Service Agency (FSA), offer crucial financial support to farmers and ranchers impacted by natural disasters such as drought, flooding, storms, wildfires, earthquakes, and other declared disasters. These loans can be used to restore or replace essential property, cover production costs, pay essential family living expenses, and refinance certain debts. The aim is to help producers recover swiftly and maintain the viability of their operations during and after disaster recovery.\n\nAdditional Benefits\nQuick Response: Provides prompt financial assistance to address immediate recovery needs following a disaster.\nEconomic Stability: Helps maintain the economic stability of farming operations and rural communities affected by disasters.\nFlexible Use: Funds can be used for a wide range of purposes to support recovery and sustainability.","eligibility":"Eligible applicants include farmers and ranchers who operate in a disaster-designated county and have experienced substantial damage or loss. Applicants must demonstrate an inability to obtain sufficient credit from other sources to cover their disaster-related needs.\n","terms":"Loan Purposes\nRestore or replace essential property (e.g., livestock, equipment, farm structures).\nCover production costs for the upcoming season.\nPay essential family living expenses.\nRefinance certain debts (excluding real estate) incurred as a direct result of the disaster.\nOrganize the farming operation to improve profitability.\n\nLoan Amounts: The maximum loan amount is up to 100% of actual production or physical losses, with a cap of $500,000.\n\nInterest Rates: Emergency loan interest rates are set by the FSA and are typically lower than conventional loan rates.\n\nRepayment Terms: Repayment terms vary according to the loan purpose and the applicant's ability to repay. Loans for crop, livestock, and non-real estate losses are typically repaid within 1 to 7 years, while loans for physical losses to real estate can be repaid up to 40 years.","applicationInstructions":"Applications must be submitted within eight months after the disaster designation date.\n\nTo apply for Emergency Farm Loans, producers must submit a loan application to their local FSA office. The application process includes providing documentation of disaster-related losses, a farm operating plan, and other required financial information. Detailed enrollment instructions and deadlines are available through the local FSA office.","resources":"https://www.fsa.usda.gov/tools/informational/rates/current-fsa-loan-interest-rates\n\nhttps://lat.fpac.usda.gov/","factSheet":"https://www.fsa.usda.gov/tools/informational/fact-sheets/emergency-loan-program-2024","programWebpage":"https://www.fsa.usda.gov/resources/programs/emergency-farm-loans","organization":"Farm Service Agency"}},{"name":"Beginning Farmers and Ranchers Loans","livestock":1,"annualCrops":1,"specialtyCrops":1,"forageHayPasture":1,"forestry":1,"irrigatedPerennial":1,"mixedOperations":1,"supportType":"Loans","droughtScore":0,"notes":"General support for entry into farming; no drought-specific function","details":{"introduction":"America's next generation of farmers and ranchers are supported through FSA's \"Beginning Farmer\" direct and guaranteed loan programs. Farm Ownership loans can provide access to land and capital. Operating loans can assist beginning farmers in becoming prosperous and competitive by helping to pay normal operating or family living expenses; open doors to new markets and marketing opportunities; assist with diversifying operations; and so much more. Through the Microloan program, beginning farmers and ranchers have an important source of financial assistance during the start-up years.\n\nWhile FSA is fully committed to all farmers and ranchers, there is a special focus on the particular credit needs of farmers and ranchers who are in their first 10 years of operation. Each year, FSA targets a portion of its lending by setting aside a portion of all loan funds for financing beginning farmer and rancher operations. With the single exception of the Direct Farm Ownership Down Payment Loan, the Beginning Farmer classification is not related to a type of loan program; it references a specific, targeted funding source.","eligibility":"A beginning farmer is an individual or entity who:\n\nHas not operated a farm or ranch for more than 10 years\n\nDoes not own a farm or ranch greater than 30 percent of the average size farm in the county as determined by the most current Census for Agriculture at the time the loan application is submitted\n\nMeets the loan eligibility requirements of the program to which he/she is applying - Farm Operating Loan, Farm Ownership Loan, or Microloan\n\nSubstantially participates in the operation","terms":"Farm Acreage Limitations\n\nHere is an example:\n\nLet's say the average size farm for \"ABC County\" is 94 acres. 30 percent of the average, rounded to the nearest tenth, is 28.2 acres. So, to meet the beginning farmer requirement, a loan applicant may not own more than 28.2 acres when the loan application is submitted.\n\nIf the farm crosses county lines and is located in more than 1 county, \"ABC County\" and \"XYZ County,\" FSA uses the average size farm data for the county where the loan applicant lives. If the loan applicant's house is not located on the farm, then the Agency looks to the data for the county in which the largest portion of the farm is located.\n\nIf you are a member of an historically underserved group or a woman farmer, the farm acreage limitation does not apply.\n\nDown Payment Loan\n\nBeing a beginning farmer is one of the requirements to be eligible for the Direct Farm Ownership Down Payment Loan. Down Payment loan funds may be used only to partially finance the purchase of a family farm. Loan applicants must contribute a minimum down payment of 5 percent of the purchase price of the farm and the Agency will finance 45 percent to a maximum loan amount of $300,150. The balance of the purchase price not covered by the down payment loan and the loan applicant's down payment may be financed by a commercial lender (XLS, 275KB), private lender, a cooperative, or the seller.","applicationInstructions":"Farmers may apply for direct loans at their local FSA offices. Your local FSA offices are listed in the telephone directory under U.S. Government, Department of Agriculture or Farm Service Agency or find your local FSA office at farmers.gov.\n\nFor guaranteed loans, applicants must apply to a commercial lender who participates in the Guaranteed Loan Program. Contact your local FSA office for a list of participating lenders.","resources":"https://www.fsa.usda.gov/state-offices\nhttps://www.fsa.usda.gov/resources/farm-loan-programs/farm-ownership-loans\nhttps://www.fsa.usda.gov/resources/farm-loan-programs/farm-operating-loans\nhttps://www.fsa.usda.gov/resources/farm-loan-programs/microloans\n","factSheet":"https://www.fsa.usda.gov/tools/informational/fact-sheets/loans-beginning-farmers-2024pdf","programWebpage":"https://www.fsa.usda.gov/resources/beginning-farmers-and-ranchers-loans","organization":"Farm Service Agency"}},{"name":"Commodity Loans","livestock":0,"annualCrops":1,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Loans","droughtScore":0,"notes":"Provides short-term financing using crops as collateral; not related to drought conditions","details":{"introduction":"Marketing Assistance Loans (MALs) offered by FSA provide producers interim financing at harvest time to meet cash flow needs without having to sell their commodities when market prices are typically at harvest-time lows.\n\nLoan Deficiency Payments (LDPs) offered by FSA are payments made to producers who, although eligible to obtain a CCC loan, agree to forgo the loan in return for a payment on the eligible commodity.","eligibility":"","terms":"Non-Recourse Marketing Assistance Loans\nMarketing assistance loans provide producers interim financing at harvest time to meet cash flow needs without having to sell their commodities when market prices are typically at harvest-time lows. Allowing producers to store production at harvest facilitates more orderly marketing of commodities throughout the year.\n\nMarketing assistance loans for covered commodities are non-recourse because the commodity is pledged as loan collateral and producers have the option of delivering the pledged collateral to the Commodity Credit Corporation (CCC) in satisfaction of the repayment of the outstanding loan for the loan at maturity. A settlement value is determined and applied to the outstanding loan principal and interest.\n\nRecourse Marketing Assistance Loan\nRecourse Marketing Assistance Loans are loans for which the commodity offered as collateral does not meet the quality eligibility requirements according to U.S. grading standards.\n\nRecourse loans must be repaid at principal plus interest. The recourse loan commodity cannot be delivered or forfeited in satisfaction of the outstanding loan.\n\nMarketing Assistance Loan and LDP Eligibility\nFor a commodity to be eligible for a marketing assistance loan or a loan deficiency payment (LDP), the producer must have beneficial interest in the commodity in addition to other eligibility requirements. For information, read the fact sheet Nonrecourse Marketing Assistance Loans and Loan Deficiency Payments.\n\nCommodity Certificate Exchange\nAgricultural producers who have a commodity pledged as collateral for a marketing assistance loan can purchase a commodity certificate that can be immediately exchanged for their outstanding loan collateral. Commodity certificates are valid only in situations where the application loan rate exceeds the exchange rate.","applicationInstructions":"Contact your local FSA office to apply.","resources":"","factSheet":"","programWebpage":"https://www.fsa.usda.gov/resources/price-support/commodity-loans","organization":"Farm Service Agency"}},{"name":"Direct Farm Operating Loan","livestock":1,"annualCrops":1,"specialtyCrops":1,"forageHayPasture":1,"forestry":1,"irrigatedPerennial":1,"mixedOperations":1,"supportType":"Loans","droughtScore":1,"notes":"Can help farmers recover from drought-related financial stress, but not drought-specific","details":{}},{"name":"Farm Ownership Loans","livestock":1,"annualCrops":1,"specialtyCrops":1,"forageHayPasture":1,"forestry":1,"irrigatedPerennial":1,"mixedOperations":1,"supportType":"Loans","droughtScore":0,"notes":"Supports land purchase; not related to drought","details":{"introduction":"With FSA's Direct Farm Ownership Loans, \"we keep America's agriculture growing.\"\n\nFarm Ownership Loans offer up to 100 percent financing and are a valuable resource to help farmers and ranchers purchase or enlarge family farms, improve and expand current operations, increase agricultural productivity, and assist with land tenure to save farmland for future generations. With a maximum loan amount of $600,000 ($300,150 for Beginning Farmer Down Payment), all FSA Direct Farm Ownership Loans are financed and serviced by the Agency through local Farm Loan Officers and Farm Loan Managers. The funding comes from Congressional appropriations as part of the USDA budget.","eligibility":"There are 3 different types of qualifications for a direct farm ownership loan which need to be met:\n\neligible farm enterprise\ngeneral eligibility requirements\nfarm management experience\nFirst, the operation must be an eligible farm enterprise. Farm Ownership loan funds cannot be used to finance nonfarm enterprises, such as exotic birds, tropical fish, dogs or horses used for non-farm purposes (racing, pleasure, show and boarding).\n\nAll loan applicants must be able to meet the following general eligibility requirements:\n\nmust not have Federal or State conviction(s) for planting, cultivating, growing, producing, harvesting, storing, trafficking, or possession of controlled substances\nhave the legal ability to accept responsibility for the loan obligation\nhave an acceptable credit history\nbe a United States citizen, non-citizen national or legal resident alien of the United States, including Puerto Rico, the U.S. Virgin Islands, Guam, American Samoa, and certain former Pacific Trust Territory\nhave no previous debt forgiveness by the Agency, including a guarantee loan loss payment\nbe unable to obtain sufficient credit elsewhere, with or without an FSA loan guarantee\nnot be delinquent on any Federal debt, other than IRS tax debt, at the time of loan closing\nnot be ineligible due to disqualification resulting from Federal Crop Insurance violation\nbe able to show sufficient farm managerial experience through education, on-the-job training and/or general farm experience, to assure reasonable prospect of loan repayment ability\nmust be the owner-operator of a family farm after loan closing","terms":"Maximum Loan Limitations\n\nThe maximum loan amount for a \"regular\" Direct Farm Ownership loan is $600,000. The maximum loan amount for a Joint Financing or Participation Farm Ownership loan is $600,000.\n\nDirect Farm Ownership Down Payment maximum loan amount works differently. The maximum loan amount under this loan program will not exceed 45 percent of whichever is the lesser amount of:\n\nthe purchase price;\nthe appraised value of the farm being purchased; or\n$667,000.\nThe balance of the purchase price not covered by the down payment loan and applicant down payment may be financed by a commercial, cooperative, or private lender, including the seller. The financing provided by FSA and all other creditors cannot exceed 95 percent of the purchase price. An FSA guarantee may be used if financing is provided by eligible lenders.\n\nInterest Rates\n\nThe interest rate charged is always the lower rate in effect at the time of loan approval or loan closing for the type of loan wanted. Interest rates are calculated and posted the 1st of each month.\n\nRepayment Terms\n\nThe maximum repayment period for the Direct Farm Ownership loan and the Joint Financing loan is 40 years.\n\nThe repayment term for FSA\u2019s portion of a Down Payment loan is 20 years. The non-FSA financing portion is required to be at least a 30 year repayment period with no balloon payment allowed within the first 20 years of the loan.","applicationInstructions":"Contact your local FSA office to apply.\n\nAll FSA direct loan applications require the same basic forms.\n\nSimultaneous requests for a direct farm ownership loan and a direct operating loan should be combined on a single loan application form.\n\nWhen you meet with your FSA county Farm Loan Program staff, you may be asked to complete additional forms based on applicable loan program requirements for the loan type.","resources":"","factSheet":"https://www.fsa.usda.gov/tools/informational/fact-sheets/farm-loans-overview-2024pdf","programWebpage":"https://www.fsa.usda.gov/resources/farm-loan-programs/farm-ownership-loans","organization":"Farm Service Agency"}},{"name":"Farm Storage Facility Loan Program (FSFL)","livestock":0,"annualCrops":1,"specialtyCrops":1,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Loans","droughtScore":0,"notes":"Supports storage infrastructure; no drought connection","details":{"introduction":"The Farm Storage Facility Loan Program (FSFL) provides low-interest financing so producers can build or upgrade permanent and portable storage facilities and equipment. Eligible commodities include grains, oilseeds, peanuts, pulse crops, hay, hemp, honey, renewable biomass commodities, fruits and vegetables, floriculture, hops, maple sap, maple syrup, milk, cheese, yogurt, butter, eggs, meat/poultry (unprocessed), rye and aquaculture. Eligible facility types include grain bins, hay barns, bulk tanks, and facilities for cold storage. Drying and handling and storage equipment is also eligible, including storage and handling trucks. Eligible facilities and equipment may be new or used, permanently affixed or portable.\n\nSince its inception in May 2000, more than 33,000 loans have been issued for on-farm storage, increasing storage capacity by 900 million bushels.\n","eligibility":"To be eligible for EGSFP, producers must have both:\nEligible grain production.\nDemonstrated a need for additional on-farm grain storage in an affected county impacted by an eligible disaster.\n\nApproved EGSFP applicants who meet the requirements for payment will receive cost-share assistance for the construction of new or renovated grain storage capacity and equipment required to meet drying and handling needs to support the orderly marketing of commodities in counties affected by these disaster events.\n\nFSA will not be able to approve and fund all eligible applications that have already been received by FSA even with the increase in initial funding.\n\nTherefore, the original application deadline has been modified to Aug. 7, 2023. For additional information on eligibility and payments, please refer to the initial NOFA for EGSFP that was published in the Federal Register on March 16, 2023.    ","terms":"FSFL is an excellent financing program for on-farm storage and handling for small and mid-sized farms, and for new farmers. Loan terms vary from 3 to 12 years. The maximum loan amount for storage facilities is $500,000. The maximum loan amount for storage and handling trucks is $100,000. In 2016 FSA introduced a new loan category, the microloan, for loans with an aggregate balance up to $50,000. Microloans offer a 5 percent down payment requirement, compared to a 15 percent down payment for a regular FSFL, and waive the regular three-year production history requirement.\n\nInterest Rates\nThe January 2026 CCC lending rates are: FSFL Rates\n\n3.500 percent per annum for FSFL with 3-year loan terms;\n3.625 percent per annum for FSFL with 5-year loan terms;\n3.875 percent per annum for FSFL with 7-year loan terms;\n4.125 percent per annum for FSFL with 10-year loan terms;\n4.250 percent per annum for FSFL with 12-year loan terms;\n ","applicationInstructions":"Loan applications should be filed in the administrative FSA county office that maintains the farm\u2019s records.","resources":"","factSheet":"https://www.fsa.usda.gov/sites/default/files/documents/fsa_egsfp_030823_final.pdf","programWebpage":"https://www.fsa.usda.gov/resources/programs/farm-storage-facility-loan-fsfl-program","organization":"Farm Service Agency"}},{"name":"Guaranteed Farm Loans","livestock":1,"annualCrops":1,"specialtyCrops":1,"forageHayPasture":1,"forestry":1,"irrigatedPerennial":1,"mixedOperations":1,"supportType":"Loans","droughtScore":0,"notes":"Indirect financial support; may help during drought recovery but not targeted","details":{"introduction":"FSA\u2019s Guaranteed Farm Loan Programs help family farmers and ranchers to obtain loans from USDA-approved commercial lenders at reasonable terms to buy farmland or finance agricultural production. FSA will guarantee farm loans through a commercial lender up to $2,343,000. Financial institutions receive additional loan business as well as benefit from the safety net the FSA provides by guaranteeing farm loans up to 95 percent against possible financial loss of principal and interest. ","eligibility":"Qualifications:\n\nTo qualify for an FSA Guarantee, a loan applicant must:\n\nBe a citizen of the United States (or legal resident alien), which includes Puerto Rico, the\u2004U.S. Virgin Islands, Guam, American Samoa, and certain former Pacific Trust Territories\n\nHave an acceptable credit history as determined by the lender\n\nHave the legal capacity to incur responsibility for the loan obligation\n\nBe unable to obtain a loan without an FSA guarantee\n\nNot have caused FSA a financial loss by receiving debt forgiveness on more than 3 occasions on or prior to April 4, 1996, or any occasion after April 4, 1996, on either an FSA direct or guarantee loan\n\nBe the owner-operator or tenant-operator of a family farm after the loan is closed. For an Operating loan, the producer must be the operator of a family farm after the loan is closed. For a Farm Ownership loan, the producer also needs to own the farm\n\nNot be delinquent on any Federal debt.\n\nConservation Loan applicants do not have to meet the \"family farm\" definition nor do they have to be unable to obtain a loan without an FSA guarantee. All other eligibility requirements must be met.","terms":"Interest Rates:\n\nThe Guaranteed loan interest rate and payment terms are negotiated between the lender\u2004and the applicant and may not exceed the maximum rates established by FSA.\n\nRepayment Terms:\n\nRepayment terms vary according to the type of loan made, the collateral securing the loan, and the producer's ability to repay. Operating Loans are normally repaid within 7 years and Farm Ownership loans cannot exceed 40 years. Operating Lines of Credit may be advanced for up to five years and all advances must be repaid within 7 years of the date of the loan guarantee.\n\nTypes of Guaranteed Farm Loans\n\nFARM OWNERSHIP loans may be used to purchase farmland, construct or repair buildings and other fixtures, develop farmland to promote soil and water conservation, or to refinance debt.\n\nFARM OPERATING loans may be used to purchase livestock, farm equipment, feed, seed, fuel, farm chemicals, insurance, and other operating expenses. Operating loans also may be used to pay for minor improvements to buildings, costs associated with land and water development, family living expenses, and to refinance debt under certain conditions. These loans may be structured as term loans or lines of credit depending upon the purpose and intended term of the loan.\n\nThe EZ GUARANTEE Program is available for smaller loans. This program provides a simplified Guaranteed Loan application process to help small, new or underserved family farmers with early financial assistance. The EZ Guarantee is available for loan applications up to $100,000 for farm operating or farm ownership purposes. Streamlined financial underwriting is available for these loans, allowing all approved lenders to analyze the request in the same manner in which they would analyze a nonguaranteed loan request of the same size and type. All existing eligibility, loan purpose, security, and other requirements remain the same.","applicationInstructions":"Your\u00a0local FSA Farm Loan Team\u00a0can help you connect with a local lender or provide you with a list of lenders known to make agricultural loans in your geographic location.\u00a0","resources":"https://www.fsa.usda.gov/resources/programs/your-guide-fsa-farm-loans","factSheet":"https://www.fsa.usda.gov/sites/default/files/documents/fsa-guaranteedloanprogram-factsheet-21.pdf","programWebpage":"https://www.fsa.usda.gov/resources/programs/guaranteed-farm-loans","organization":"Farm Service Agency"}},{"name":"Marketing Assistance for Specialty Crops (MASC)","livestock":0,"annualCrops":1,"specialtyCrops":1,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Loans","droughtScore":0,"notes":"Supports marketing and cash flow; not drought-related","details":{"introduction":"The Marketing Assistance for Specialty Crops (MASC) program provides financial assistance to specialty crop producers to help them expand domestic markets or develop new markets for their crops. \n\nMASC helps specialty crop producers offset higher marketing costs related to:\n\nTenderness and perishability of specialty crops like fruits, vegetables, floriculture, nursery crops and herbs;\nSpecialized handling and transport equipment with temperature and humidity control;\nPackaging to prevent damage;\nMoving perishables to market quickly; and\nHigher labor costs. ","eligibility":"MASC covers the following commercially marketed specialty crops grown in the US:\n\nFruits (fresh, dried);\n\nVegetables (including dry edible beans and peas, mushrooms, and vegetable seed);\n\nTree nuts;\n\nNursery\u2004crops, Christmas trees, and floriculture;\n\nCulinary and medicinal herbs and spices; and\n\nHoney, hops, maple sap, tea, turfgrass, and grass seed.\n\nCommon examples of specialty crops can be found on USDA\u2019s Agricultural Marketing Service\u2019s specialty crop definition webpage. \n\nEligible producers or legal entities must:\n\nHave an average adjusted gross income (AGI) of less than $900,000 for tax years 2021, 2022, and 2023, unless the producer or legal entity\u2019s average adjusted gross farm income is at least 75 percent of their average AGI;\n\nBe in the business of producing a specialty crop at the time of application and be entitled to an ownership share and share in the risk of producing a specialty crop that will be sold in calendar year 2025;\n\nBe a U.S. citizen, resident alien, partnership, corporation, limited liability company, or other organizational structure organized under state law, Indian Tribe or Tribal Organization, or a foreign person or foreign entity who meets certain eligibility requirements;\n\nComply with the provisions of the \u201cHighly Erodible Land and Wetland Conservation\u201d regulations, often called the conservation compliance provisions; and\n\nNot have a controlled substance violation.","terms":"FSA will issue MASC payments after the end of the application period. If demand for MASC payments exceeds available funding, MASC payments may be prorated, and the payment limitation of $900,000 may be lowered. If additional funding is available after MASC payments are issued, FSA may issue an additional payment.\n\nFor established specialty crop growers, those who certify crop sales in 2023 or 2024, FSA will calculate MASC payments based on the producer\u2019s total specialty crop sales for the calendar year elected by the producer. \n\nPayments for new producers will be based on their expected 2025 calendar year sales and must submit FSA-1141 (FSA-1141-Spanish), Marketing Assistance for Specialty Crops (MASC) New Producer Expected Sales Worksheet.  Additionally, instructions for FSA-1140 (Instrucciones para FSA-1140) are available.\n","applicationInstructions":"Eligible producers or legal entities must submit a complete Form FSA-1140 (FSA-1140-Spanish) MASC Application to any FSA county office by Jan. 8, 2025. Additionally, instructions for FSA-1140 (Instrucciones para FSA-1140) are available. FSA staff at your local USDA Service Center will work with you to file your application.","resources":"","factSheet":"https://www.fsa.usda.gov/sites/default/files/2024-12/FSA_MASC_FACTSHEET1_24c_0.pdf","programWebpage":"https://www.fsa.usda.gov/resources/programs/marketing-assistance-specialty-crops-masc","organization":"Farm Service Agency"}},{"name":"Marketing Assistance Loans","livestock":0,"annualCrops":1,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Loans","droughtScore":0,"notes":"Commodity price support; not drought-related","details":{"introduction":"The Marketing Assistance Loans (MAL) program, administered by the Farm Service Agency (FSA), offers loans to producers of eligible commodities to help manage their cash flow needs and provide marketing flexibility. By using their harvested commodities as collateral, producers can obtain interim financing and delay the sale of their crops until market prices improve. MALs help stabilize agricultural income and ensure that farmers have the financial resources to continue their operations.\n\nEligible commodities include:\n\nBarley\nCanola\nChickpeas (large and small)\nCorn\nCrambe\nDry peas\nFlaxseed\nGrain sorghum\nHoney\nLentils\nMohair\nMustard seed\nOats\nPeanuts\nRapeseed\nRice\nSafflower seed\nSesame seed\nSoybeans\nSunflower seed\nUpland cotton\nWheat\nWool (graded and ungraded)\n\nAdditional MAL Benefits\nMarketing Flexibility: MALs provide producers with the flexibility to sell their commodities when market conditions are more favorable, potentially increasing their revenue.\nPrice Support: By offering interim financing, MALs help stabilize commodity prices and provide a safety net for producers during periods of low market prices.\nEligible Commodities: In addition to common field crops, the program covers wool, mohair, honey, peanuts, and pulse crops such as lentils, small chickpeas, and dry peas.","eligibility":"Eligible applicants include producers of designated commodities who meet conservation and wetland protection requirements and provide sufficient documentation of their commodities. Producers must comply with all program requirements to qualify for a loan.","terms":"Loan Terms: MALs provide short-term loans with terms up to nine months. The loans use the harvested commodity as collateral, and the loan amount is based on the established loan rate for the commodity.\n\nLoan Rates: Loan rates are established by the USDA and vary by commodity and location. These rates are intended to reflect local market conditions and storage costs.\n\nRepayment: Producers can repay the loan at the lesser of the loan rate plus interest or the posted county price (PCP). Alternatively, producers can forfeit the commodity to the CCC as full payment for the loan at maturity.","applicationInstructions":"To apply for Marketing Assistance Loans, producers must complete and submit a loan application to their local FSA office. The application process includes providing documentation of the eligible commodity, production records, and proof of compliance with program requirements. Detailed enrollment instructions and deadlines are available through the local FSA office.","resources":"","factSheet":"https://www.fsa.usda.gov/tools/informational/fact-sheets/nonrecourse-marketing-assistance-loans-loan-deficiency-payments","programWebpage":"https://www.fsa.usda.gov/resources/programs/marketing-assistance-loans-mal","organization":"Farm Service Agency"}},{"name":"Microloan Programs","livestock":1,"annualCrops":1,"specialtyCrops":1,"forageHayPasture":1,"forestry":1,"irrigatedPerennial":1,"mixedOperations":1,"supportType":"Loans","droughtScore":1,"notes":"Flexible financing; may support adaptation (e.g., water systems), but not drought-specific","details":{"introduction":"The focus of Microloans is on the financing needs of small, beginning farmer, niche and non-traditional farm operations, such as truck farms, farms participating in direct marketing and sales such as farmers\u2019 markets, CSA\u2019s (Community Supported Agriculture), restaurants and grocery stores, or those using hydroponic, aquaponic, organic and vertical growing methods.","eligibility":"As with the regular Operating loan program, traditional and non-traditional family farms and ranches may be eligible for Microloan financing.\n\nGeneral eligibility requirements include:\n\nMust not have Federal or State conviction(s) for planting, cultivating, growing, producing, harvesting, storing, trafficking, or possession of controlled substances\n\nHave the legal capacity to incur the loan obligation\n\nBe able to show an acceptable credit history\n\nIs a citizen, non-citizen\u2004national or legal resident alien of the United States, including Puerto Rico, the U.S. Virgin Islands, Guam, American Samoa, and certain former Pacific Trust Territories\n\nHave no previous debt forgiveness by the Agency, including a guarantee loan loss payment\n\nBe unable to obtain sufficient credit elsewhere, with or without an FSA loan guarantee\n\nNot be delinquent on any Federal debt, other than IRS tax debt, at the time of loan closing\n\nNot be ineligible due to disqualification resulting from Federal Crop Insurance violation","terms":"Loan Limitations\n\nThere is no minimum loan amount. The maximum loan amount for either Microloan is $50,000. The $50,000 limit includes any possible outstanding FSA Direct Operating or Farm Ownership unpaid principal loan balances. A loan applicant may have a Guaranteed Operating loan, Farm Ownership loan or Emergency loan and still qualify for a Microloan.\n\nInterest Rates\n\nFSA\u2019s Direct Operating loan interest rate applies to Operating Microloans. FSA's Direct Farm Ownership loan interest rate applies to Farm Ownership Microloans. The interest rate charged is always the lower rate in effect at the time of loan approval or loan closing for the type of loan wanted. Interest rates are calculated monthly and are posted on the 1st of each month.\n\nRepayment Terms\n\nFor the Direct Ownership Microloan, the maximum term is 25 years.\n\nFor the Direct Operating Microloan, the repayment period will vary depending upon the purpose of the loan. General operating and family living expenses are due within 12 months or when the agricultural commodities sell. For larger purchases such as equipment or livestock, the term will not exceed 7 years.","applicationInstructions":"It recommended that you call and make an appointment with your nearest Farm Loan Officer or Farm Loan Manager(https://www.fsa.usda.gov/state-offices). Agency officials are required to:\n\u2022\tHelp loan applicants complete FSA forms and gather information necessary for a complete application;\n\u2022\tExplain the application procedure, process, and the requirements for a complete application;\n\u2022\tAssist loan applicants in completing FSA forms and identifying sources of\u2004information needed for a complete application, if assistance is requested;\n\u2022\tInform loan applicants of other technical assistance providers who may be of assistance at minimal or no charge. Some examples include, and are not limited to, the Cooperative Extension Service, non-profit organizations and institutions, the Intertribal Agriculture Council, and other similar organizations; and\n\u2022\tAdvise applicants of alternatives that will help overcome any possible barriers to being determined eligible for an FSA loan.\nSuggestions for First Meeting with FSA\n\u2022\tHave a general idea of what it is you want to do and be able to identify your goals. What type of operation do you have or want to have? What do you need to operate that farm or ranch? How will you market your product(s)? How much do you need? What are your projections?\n\u2022\tGood recordkeeping is very important. If you do not have your records organized, it is a good idea to try and put all your income and expenses into an understandable format. It does not have to be fancy. Also, what is happening inside the household is just as important as your business needs. Expenses such as food, clothing, mortgage or rent, insurance, taxes, medical costs, credit card payments, education expenses, and other consumer debt are part of the farm plan calculations. Know your costs. Bring your records with you.\n\u2022\tRemember to bring any financial records, which can include tax returns, for the most recent production cycle to assist in projecting the cash flow for your loan proposal. If you need to rely on off-farm income to repay the loan, bring in your last few pay stubs.\n\u2022\tBring copies of any written leases to the office with you if you are leasing land or equipment.\n\u2022\tIt is a prudent idea to check your credit report before applying for a loan. This allows you to spot any errors or research events that may have negatively impacted your credit. The Fair Credit Reporting Act (FCRA) requires each of the nationwide credit reporting companies\u2014Equifax, Experian, and TransUnion\u2014to provide you with a free copy of your credit report, at your request, once every 12 months. The FCRA promotes the accuracy and privacy of information in the files of the nation's credit reporting companies. The Federal Trade Commission (FTC), the nation's consumer protection agency, enforces the FCRA with respect to credit reporting companies.\n\u2022\tMany answers can be found in the booklet, \"Your Guide to FSA Farm Loans.\n","resources":"https://farmanswers.org/\nhttp://agrability.org/\nhttps://www.ams.usda.gov/services/organic-certification/is-it-an-option\nhttps://newfarmers.usda.gov/veterans\nhttps://www.farmers.gov/\n","factSheet":"https://www.fsa.usda.gov/tools/informational/fact-sheets/microloans-2024pdf","programWebpage":"https://www.fsa.usda.gov/resources/farm-loan-programs/microloans","organization":"Farm Service Agency"}},{"name":"Rural Energy for America Program (REAP)","livestock":1,"annualCrops":1,"specialtyCrops":1,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":1,"mixedOperations":1,"supportType":"Loans","droughtScore":1,"notes":"Supports energy and water efficiency (e.g., irrigation systems), which can improve drought resilience","details":{"introduction":"The program provides guaranteed loan financing and grant funding to agricultural producers and rural small businesses for renewable energy systems or to make energy efficiency improvements. Agricultural producers may also apply for new energy efficient equipment and new system loans for agricultural production and processing.","eligibility":"Who may apply for this program?\n\u2022\tAgricultural producers with at least 50 percent of their gross income coming from agricultural operations.\n\u2022\tSmall businesses in eligible rural areas.\nNOTE: Agricultural producers and small businesses must have NO outstanding delinquent federal taxes, debt, judgment or debarment.\nWho may qualify for loan guarantees?\nEligible\u2004borrowers are:\n\u2022\tRural small businesses\n\u2022\tAgricultural producers\nWhat are the borrowing restrictions for loan guarantees? \n\u2022\tIndividual borrowers must be citizens of the United States or reside in the U.S. after being legally admitted for permanent residence.\n\u2022\tPrivate-entity borrowers must demonstrate that loan funds will remain in the U.S.\nWhat is an eligible area?\n\u2022\tBusinesses must be in located in rural areas with populations of 50,000 residents or less. \n\u2022\tCheck eligible business addresses.\n\u2022\tAgricultural producers may be in rural or non-rural areas.\n\n","terms":"What funding is available?\n\nLoan guarantees on loans up to 75 percent of total eligible project costs.\n\nGrants for up to 50 percent of total eligible project costs.\n\nCombined grant and loan guarantee funding up to 75% of total eligible project costs.\n\nWhat is the maximum amount of a loan guarantee?\n\nThe loan guarantee percentage\u2004is published annually in a Federal Register notice.\n\nWhat are the loan guarantee terms?\n\nThe lender, with Agency concurrence, will establish and justify the guaranteed loan term based on the use of guaranteed loan funds, the useful economic life of the assets being financed and those used as collateral, and the borrower's repayment ability. The loan term will not exceed 40 years.\n\nWhat are the interest rates for the loan guarantee?\n\nInterest rates are negotiated between the lender and borrower.\n\nRates may be fixed or variable.\n\nVariable interest rates may not be adjusted more often than quarterly.\n\nWhat are the applicable fees for the loan guarantee?\n\nThere is an initial guarantee fee, currently 1 percent of the guaranteed amount.\n\nThere is a guarantee retention fee, currently 0.25 percent of the outstanding principal balance, paid annually.\n\nReasonable and customary fees for loan origination are negotiated between the borrower and lender.\n\nWhat are the underwriting requirements for the loan guarantee?\n\nThe lender will conduct a credit evaluation using credit documentation procedures and underwriting processes that are consistent with generally accepted prudent lending practices and also consistent with the lender's own policies, procedures and lending practices.\n\nThe lender's evaluation must address any financial or other credit weaknesses of the borrower and project and discuss risk mitigation requirements.\n\nThe lender must analyze all credit factors to determine that the credit factors and guaranteed loan terms and conditions ensure guaranteed loan repayment.\n\nCredit factors to be analyzed include but are not limited to character, capacity, capital, collateral, and conditions.  ","applicationInstructions":"Please select your state in the dropdown menu above to find the state office contact information and speak to a program specialist before attempting to fill out any forms or applications. This will save you time in completing your application.","resources":"","factSheet":"https://www.rd.usda.gov/sites/default/files/508_RD_FS_RBS_REAP_RE_EE.pdf","programWebpage":"https://www.rd.usda.gov/programs-services/energy-programs/rural-energy-america-program-renewable-energy-systems-energy-efficiency-improvement-guaranteed-loans","organization":"Rural Development"}},{"name":"Veterans Affair's Loans for Farms","livestock":1,"annualCrops":1,"specialtyCrops":1,"forageHayPasture":1,"forestry":1,"irrigatedPerennial":1,"mixedOperations":1,"supportType":"Loans","droughtScore":0,"notes":"General access to capital; no drought relevance","details":{"introduction":"The Department of Veterans Affairs\u2019 (VA) Home Loan benefit may be used to purchase a\nfarm. There must be a farm residence on the land, and the Veteran must live in it as his\nor her primary residence. VA-guaranteed loans can only be used for residential\npurposes, and not to purchase a business. This means that some farm properties may\nnot be eligible for purchase using a VA-backed home loan.","eligibility":"","terms":"Loans for farm dwellings are appraised the same way as for nonfarm-type dwellings:\n\nVA does not limit the number of acres a VA-guaranteed property may have.\n\nThe appraisal of properties with acreage should not pose a problem, as long as similar properties in the area were recently sold primarily for residential use. This may include improvements not typically considered residential, like barns, sheds, corrals, stables and pastures.\n\nFor VA purposes, the value must not include\u2004livestock, crops, or farm equipment and supplies. Individual improvements not typically considered residential will be valued at fair market value. This includes barns, sheds, corrals, stables, pastures, etc.\n\nUnderwriting guidelines are generally the same as for nonfarm-type dwellings.\n\nFor example, some or all of the income necessary to support the loan payments may come from farming operations. In this case, VA must verify the Veteran's ability and experience as a farm operator. Updated August 2018 2\n\nThe procedures and analysis in Chapter 4 of VA Pamphlet 26-7, \"Lenders Handbook\", under \"Self-Employment Income\" generally apply.","applicationInstructions":"Apply for a Certificate of Eligibility (COE). You can apply online using eBenefits at www.ebenefits.va.gov/, or fill out VA Form 26-1880, \"Request for Certificate of Eligibility.\" Download the form from www.vba.va.gov/pubs/forms/vba-26-1880-are.pdf. See page 2 of the form for the mailing address of your regional loan center. Lenders can also get COEs for Veterans online.\n\nFind a realtor and lender to help you through the process of buying a home. The lender will complete an application and help you\u2004determine the amount you qualify for. Once prequalified or pre-approved, the realtor can show you homes within your price range.\n\nChoose a home, and sign a purchase agreement with the seller or a contract with a builder. Your sale contract should include a provision that voids the sale if you are unable to get VA-guaranteed financing.\n\nThe lender will order an appraisal of the property. Lenders also help you clear the final conditions required to close on your new home.","resources":"","factSheet":"","programWebpage":"https://www.benefits.va.gov/BENEFITS/factsheets/homeloans/FarmLoans.pdf","organization":"Department of Veterans Affairs"}},{"name":"Oregon Aggie Bond Program","livestock":0,"annualCrops":1,"specialtyCrops":1,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":1,"mixedOperations":0,"supportType":"Loans","droughtScore":0,"notes":"State-level financing tool; not drought-specific","details":{"introduction":"The Beginning and Expanding Farmer Loan Program, better known as the Aggie Bond Program, provides affordable financing to new farmers for financing capital purchases.\n\nThe program allows the lender to avoid paying income taxes on interest the lender receives from the borrower. The lender can pass this savings on to the borrower in the form of a lower interest rate. The State of Oregon does not provide a repayment guarantee of the Aggie Bond. The lender assumes all credit risks, and the borrower is solely responsible for repaying the Aggie Bond.\n\n","eligibility":"A person must:\n\nBe an Oregon resident\n\nHave a net worth of no more than $750,000\n\nBe a principal user of the farm and materially and substantially participate on the farm\n\nHave never owned/operated a farm that was larger than 30% of the county's median farm size","terms":"The maximum Aggie Bond financing is $520,000. Aggie Bond financing can be used for:\n\nPurchase of farm land\n\nCosts of depreciable farm property. Financing of new depreciable property (such as construction of farm buildings and new equipment) is limited to $250,000. Financing of used depreciable farm property is\u2004limited to $62,500.\n\nMost entities that are in the business of making agricultural loans (such as commercial banks and Northwest Farm Credit Services) are eligible to be Aggie Bond lenders. A lender may not be a substantial user of the financed property, or related to a substantial user of that property. The Aggie Bond Program has some unique features, and works most easily with eligible lenders who have reviewed the program requirements and expressed an interest in participating.","applicationInstructions":"\u200bTo apply, farmers should first find an eligible lender willing to provide financing, then submit the Beginning and Expanding Farmer Loan Program Application form to Business Oregon. \u200b\u200b","resources":"","factSheet":"","programWebpage":"https://www.oregon.gov/biz/programs/aggiebond/pages/default.aspx","organization":"Business Oregon"}},{"name":"Water Well Trust Water Access Program","livestock":1,"annualCrops":1,"specialtyCrops":1,"forageHayPasture":1,"forestry":1,"irrigatedPerennial":1,"mixedOperations":1,"supportType":"Loans","droughtScore":2,"notes":"Directly improves water access","details":{"introduction":"The Water Well Trust (WWT) and its partners provide funding for wells and/or septic systems for low\u2010income families nationwide that need safe drinking water or wastewater systems. We serve Americans living primarily in rural, unincorporated areas or minority communities that may be isolated and difficult to reach. We assist low\u2010income families that do not have access to public water supplies or sewer, and those who live in areas where the extension of public water supplies to serve them doesn\u2019t make economic sense\u2026for them, for the public water supply owners, for federal, state or local funding sources.","eligibility":"To be eligible\u2004for a loan, you must meet all following eligibility criteria:\n\nDeed or mortgage for home and property in applicant\u2019s name.\n\nApplicant must be the occupant(s) of the property.\n\nHome must be applicant\u2019s primary residence.\n\nNo new construction, must have occupied the property for at least one year.\n\nNo reliable source of water to the home and no option to connect to a public water utility or sewer.\n\nGross annual household income based on your state\u2019s median non-metropolitan household income. ","terms":"","applicationInstructions":"To apply, complete this online form(https://www.waterwelltrust.org/online-app-info/) and WWT will contact you.\nOr contact WWT by calling 833-539-8200 or by email at info@waterwelltrust.org.\n","resources":"http://www.waterwelltrust.org/","factSheet":"","programWebpage":"https://www.waterwelltrust.org/apply/","organization":"Water Well Trust"}},{"name":"Harvest Returns","livestock":1,"annualCrops":0,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Loans","droughtScore":0,"notes":"Private investment platform; no drought relevance","details":{"introduction":"Farmers, ranchers, and agribusinesses often need capital to expand their operations or acquire new land. Most farmers automatically seek ag credit lenders for capital, because it\u2019s what we all know as a traditional funding source. But there are other ways besides bank loans to receive the needed capital. The use of equity partners in crowdfunding is an alternate way to finance land acquisition.","eligibility":"Who should raise capital with Harvest Returns?\n\nEstablished US-based agribusinesses that need flexible capital to expand their operations or develop value-added processing facilities ($500,000 - $10 million).\n\nExperienced farmers, growers, ranchers, and landowners interested in expanding their operations or acquiring new land.\n\nProducers who need equity to buy out partners on a multi-generational farm.\n\nLivestock ranchers who want flexible financing to grow their herds.\n\nCompanies or individuals needing equity or debt funding to acquire an existing agribusiness.\n\nHardware or infrastructure companies needing a financing partner\n\nEarly stage Agtech companies generating revenue who are raising a Seed - Series B Round (our average check size is $500,000). We invest in equity or convertible debt rounds.\n\nAg businesses in a designated Opportunity Zone. In 2026, we\u2019re especially looking for farms/businesses in newly designated Rural Opportunity Zones.","terms":"","applicationInstructions":"If your project meets our requirements, we will request additional documents to learn more about your project. A clear and transparent business plan coupled with organized and complete financial projections are the best starting point.\nListing Agreement\n\nThe agreement lays out the terms of the crowdfunding raise and what you can expect from the process as far as time, effort, and costs to you.\nLive on Platform\n\nAfter the project is set up\u2004and ready for investors, it goes live on the platform to accept investors from qualified investors. Harvest Returns will work to help you maximize the chances of a successful raise and maintain compliance with U.S. Securities regulations.\nClose Raise & Receive Funds\n\nYou will receive the funds after the raise has successfully closed. You will work with Harvest Returns over the course of the operation to keep investors updated, provide financial statements and tax documents, and make investor distributions.","resources":"https://www.harvestreturns.com/how-our-platform-works/","factSheet":"","programWebpage":"https://www.harvestreturns.com/for-agproducers","organization":"Harvest Returns"}},{"name":"Steward Loans","livestock":0,"annualCrops":0,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Loans","droughtScore":0,"notes":"General sustainability financing; not explicitly drought-focused","details":{"introduction":"Unlike traditional banks or lenders, Steward is 100%-focused on financing regenerative food systems.\n\nAs a commercial lender and financing partner to projects throughout the value chain, we offer customized loan terms as well as professional expertise, both tailored to the specific needs of each project.","eligibility":"You use regenerative and/or environmentally sustainable management practices in your production, sourcing, or supply chain. Steward also helps businesses who are committed to responsible stewardship make the transition to regenerative management.\n\nYou have at least 3 years of experience owning or managing a commercial farm, agricultural operation, or food business with established markets and sales channels. Steward offers commercial loans to registered businesses only.\n\nYou're able to demonstrate that your business has an ability to service debt from current or projected cash flows, and to produce financial statements and projections upon request.","terms":"","applicationInstructions":"https://gosteward.com/login","resources":"","factSheet":"","programWebpage":"https://gosteward.com/borrow","organization":"Steward"}},{"name":"Grass Fed Small & Very Small Producer Program (SVS)","livestock":1,"annualCrops":0,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Markets & Supply Chains","droughtScore":0,"notes":"Market support for livestock products; no drought focus","details":{"introduction":"The USDA Grass Fed Program for Small and Very Small (SVS) Producers was designed to create opportunities for small-scale livestock producers who would like to have their ruminant animals certified as grass fed.  ","eligibility":"This program, is designed for producers who market 49 cattle or\u2004less each year or lambs produced from 99 ewes or less.\n\nThis program requires that ruminant animals be fed only grass and forage, with the exception of milk consumed prior to weaning. Animals certified under this program cannot be fed grain or grain by-products and must have continuous access to pasture during the growing season.\n\nThe \u201c49 cattle or less\u201d or \u201clambs produced from 99 or less ewes\u201d rule is based upon the smallest groups identified in the Census of Agriculture.","terms":"Cost of the Service: The set fee for the review is $175.00/hour.\n\nDuration of the approval: Two year period.","applicationInstructions":"AMS reviews a producer\u2019s application and detailed farm/ranch plan.  If the information is sufficient, AMS approves the producer and the cattle and/or sheep as meeting the requirements of the USDA Grass Fed Program for Small and Very Small (SVS) Producers.  Producers certified under this program receive a certificate that allows them to market cattle and sheep as USDA Certified grass-fed.\n","resources":"https://www.ams.usda.gov/resources/lp1020c\nhttps://www.ams.usda.gov/resources/lp1020s\n","factSheet":"","programWebpage":"https://www.ams.usda.gov/services/auditing/grass-fed-SVS","organization":"Agricultural Marketing Service"}},{"name":"Organic Dairy Marketing Assistance Program (ODMAP)","livestock":1,"annualCrops":0,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Markets & Supply Chains","droughtScore":0,"notes":"Supports organic dairy markets; not drought-related","details":{"introduction":"The Organic Dairy Marketing Assistance Program (ODMAP 2024), administered by the Farm Service Agency (FSA), offers payments to eligible organic dairy producers. ODMAP 2024 provides a one-time cost-share payment based on marketing costs on pounds of organic milk marketed in the 2023 calendar year or estimated 2024 marketing costs for organic dairy operations that have increased milk production.","eligibility":"Applicant Eligibility\n\nProduce milk from cows, sheep or goats\nProvide USDA organic certification\nCertify to amount of organic milk marketed in 2023\nComplete and submit FSA-630 application","terms":"Payment Rate: ODMAP 2024 provides for an increase in the payment rate to $1.68 per hundredweight compared to the previous $1.10 per cwt. Additionally, the production cap has increased to nine million pounds compared to the previous five million pounds.","applicationInstructions":"To apply for the Organic Dairy Marketing Assistance Program, producers must complete and submit an ODMAP 2024\u00a0application to their local FSA office. The application process includes certifying to 2023 milk production and providing supporting documentation. Detailed enrollment instructions and deadlines are available through the local FSA office.","resources":"","factSheet":"","programWebpage":"https://www.fsa.usda.gov/resources/programs/organic-dairy-marketing-assistance-program-odmap","organization":"Farm Service Agency"}},{"name":"Agoro Carbon","livestock":0,"annualCrops":1,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Markets & Supply Chains","droughtScore":1,"notes":"Encourages soil carbon practices that improve soil moisture and drought resilience","details":{"introduction":"Agoro Carbon\u2122 designed our program to support you in making practical and profitable soil-health practice changes. Not only can these changes generate additional income through carbon credits, but they can also improve soil health while helping lower future management costs. Your operation can see enhanced yields, cost savings, more resilient, healthier fields and pastures, and many other benefits for years to come.","eligibility":"Eligible Practices\nCover Crops\nIncreased Biodiversity\nPrescribed Grazing\nNutrient Management\nReduced- or No-Till\nWildlife Habitat Planting\n\nAdditionality Requirement\nYes, with a look-back of 3 years","terms":"Payment Schedule\nTwo options:\n1. Carbon Performance Based Payments: payments years 5 and 11 based on credit issuance\n2. Carbon Prepayments: annual payments in addition to payments years 5 and 11 based on credit issuance. Annual payments are deducted from issuance payments.\n\nPrice\nTwo Options: Option A floor prices are at $18/ton at year 5 and $20/ton at year 11. Option B floor prices at year 5 price is $16.50/ton and $20/ton in year 11. Average year 1 payment per acre is highly dependent on practices enrolled in/payment option enrolled in/location. Visit program website to connect with a representative and receive a personalized quote.\n\nStackability (With goverment programs and other markets)\nYes, some programs are able to stack with Agoro Carbon enrollment. Please connect with a representative to talk over your specific scenario\n\nCarbon Related Incentive\nOffset\n\nContract Length\n10 years","applicationInstructions":"Data Collected at Enrollment\n3-year historical data summary, including information on tillage, planting, harvest, chemical and fertilizer applications, and irrigation if applicable. Assistance from an Agoro Carbon Grower Success Team Member and Sales Manager throughout the enrollment process and the length of the contract\n\nEnrollment Assistance\nYes, Agoro Carbon promises a free consultation with an agronomist throughout the duration of the contract\n\nAgronomic/Technical Assistance\nAgoro Carbon helps collect data and handles administration activities, including auditing and certification. They also provide the soil sampling as part of the verification process, secure buyers for credits, and provide a local contact to correspond with.","resources":"","factSheet":"","programWebpage":"https://agorocarbonalliance.com/our-carbon-program/","organization":"Agoro Carbon"}},{"name":"CarbonNOW","livestock":0,"annualCrops":1,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Markets & Supply Chains","droughtScore":1,"notes":"Supports soil health practices; indirectly improves drought resilience","details":{"introduction":"Locus Agricultural Solutions\u2019 CarbonNOW program generates carbon credits through the use of its soil probiotics. They have partnered with Bluesource, a well known carbon credit developer to assist with the issuance of credits. ","eligibility":"Geography\nNationwide\n\nEligible Practices\nCover Crops\nNutrient Management\nReduced- or No-Till\n\nAdditionality Requirement\nYes. However, if already utilizing regenerative agricultural practices, using Locus AG\u2019s product qualifies as a new practice change.","terms":"Payment Schedule\nTwo annual disbursements: $12/acre per year guaranteed. $9/acre paid at completion of soil sampling. $3/acre paid at end of year with year-end data collected.\n\nPrice\nAnnual payments of $12/acre, with annual performance bonuses based on carbon sequestered.\n\nStackability (With goverment programs and other markets)\nCan be stacked with other governmental programs.\n\nCarbon Related Incentive\nOffset\n\nContract Length\n4 year minimum with opportunity to renew\n\nPenalty for Temporary Break in Practice Implementation","applicationInstructions":"Data Collected at Enrollment\n3-5 years of historical management data, field areas, and information on regenerative practices changes. Data collection led by Locus AG with minimal farmer time required.\n\nEnrollment Assistance\nTo check eligibility, visit https://locusag.com/eligibility. A CarbonNOW expert will be in touch within 2 business days to answer questions, check eligibility and begin data collection process.\n\nAgronomic/Technical Assistance\nParticipants are assigned a program steward that provides full program management, plus continuing consultation to boost on-farm ROI.","resources":"","factSheet":"","programWebpage":"https://unitedsoybean.org/usb-carbon-toolbox/carbon-programs/carbonnow/","organization":"CarbonNOW"}},{"name":"CIBO","livestock":0,"annualCrops":1,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Markets & Supply Chains","droughtScore":1,"notes":"Promotes regenerative practices linked to soil moisture retention","details":{"introduction":"Combine federal funding with private sustainability payments, insurance products and financing solutions to attract more farmers faster. Unlock higher participation and stronger outcomes per dollar invested with automated eligibility checks, streamlined applications and legal incentive stacking all in one platform.","eligibility":"Geography\nNorth America\n\nEligible Practices\nCarbon Sequestration\nGHG emissions reduction\nIncreased Biodiversity\nRegenerative Ag\nSoil Health. Other programs may have different combinations of eligible practices.\n\nAdditionality Requirement\nVaries by program. Verra-verified carbon credit programs have strict additionality requirements. Other programs have fewer or no additionality requirements.","terms":"Payment Schedule\nVaries by program\n\nPrice\nVaries by program\n\nStackability (With goverment programs and other markets)\nGenerally, Yes. Many programs on the CIBO Impact platform are stackable with other incentives. Some programs are not stackable.\n\nCarbon Related Incentive\nCombination\n\nContract Length\nVaries by program\n\nPenalty for Temporary Break in Practice Implementation\nVaries by program.","applicationInstructions":"Data Collected at Enrollment\nVaries by program. May include crop rotation, cover cropping, and tillage type, field boundaries, and N-applied for the growing season for which the grower is enrolling.\n\nEnrollment Assistance\nEnrollment may be initiated by a grower\u2019s trusted advisor, agronomist, crop consultant, or program sponsor. Growers must be in the loop for any contractual agreement. Technical and platform support is provided by CIBO\u2019s Customer Success team To request a demo, visit https://www.cibotechnologies.com/request-a-demo/\n\nAgronomic/Technical Assistance\nAgronomic support is provided by program sponsors and CIBO\u2019s network of grower representatives, coops, and associations.","resources":"","factSheet":"","programWebpage":"https://www.cibotechnologies.com/","organization":"CIBO"}},{"name":"Low Carbon Technologies, LLC","livestock":0,"annualCrops":1,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Markets & Supply Chains","droughtScore":1,"notes":"Supports climate-smart practices; may improve drought resilience indirectly","details":{"introduction":"Today's consumers demand more than mere sustainability pledges and labels; they seek assurance backed by scientific rigor. As a proud service provider accredited by the United States Department of Agriculture (USDA), Low Carbon Technologies (LCT) delivers environmentally conscious certifications so we can all feel good about what we're putting on the grill or in our glass.","eligibility":"Geography\nNationwide\n\nEligible Practices\nCover Crops\nNutrient Management\nPasture and Hay Planting\nPrescribed Grazing\nRange Planting\n\nAdditionality Requirement\nDoes not specify","terms":"Payment Schedule\nDoes not specify\n\nPrice\n1.Written fertilizer and soil management plans: $10/acre for cover crop acreage and $5/acre for forage or range acreage\n2. Multispecies cover crop planting on cropland for feed or grazing: $40/acre\n3. Forage/biomass planting on pasture land: $75/acre\n4. Conversion of cropland to rangeland or enhancement of range planting: $100/acre\n\nStackability (With goverment programs and other markets)\nNo double-counting for federal sources\n\nCarbon Related Incentive\nNot applicable\n\nContract Length\nThe Partnership for Climate Smart Commodities program is a five year program starting in February 2023.","applicationInstructions":"Data Collected at Enrollment\nAll projects are required to include plans to (1) quantify greenhouse gas (GHG) benefits and (2) monitor/verify those benefits over time.\n\nEnrollment Assistance\nDoes not specify\n\nAgronomic/Technical Assistance\nThis project will use Vytelle SENSE to identify high performing animals for reproducing based on feed intake, weights & behavior. Vytelle INSIGHT will help producers make genetics selections based on dry matter intake & enteric methane emissions. AgSpire will provide technical assistance, practice implementation advice, and cost-share program assistance.","resources":"","factSheet":"","programWebpage":"https://www.lowcarbontech.com/","organization":"Low Carbon Technologies, LLC"}},{"name":"Nutrien","livestock":0,"annualCrops":1,"specialtyCrops":1,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Markets & Supply Chains","droughtScore":1,"notes":"Provides programs for soil and nutrient management; some benefits for water retention","details":{"introduction":"Receive a minimum of $2/acre when you reduce your applied nitrogen by a minimum of 5%. Enter and commit the data in your Agrible\u00ae account to maintain eligibility. Your program incentive is based on outcomes, calculated at a rate of $35/ton for total tons of greenhouse gas (GHG) emissions reduced on your operation, with a minimum outcome payment of $2/acre.","eligibility":"Geography\nAvailable in all of North America\n\nEligible Practices\nNutrient Management\n\nAdditionality Requirement\nYes","terms":"Payment Schedule\nAt the end of the crop year after practice implementation is verified.\n\nPrice\nMinimum of $1.50 per acre, with averages of $3-4 per acre.\n\nStackability (With goverment programs and other markets)\nRefer to program category descriptions for general stackability potential. Reach out to the program contact for more information.\n\nCarbon Related Incentive\nOffset\n\nContract Length\n1 year contracts with potential annual re-enrollment for up to 10 years\n\nPenalty for Temporary Break in Practice Implementation\nNot required, as it is based solely on if the practice change was implemented","applicationInstructions":"Data Collected at Enrollment\nAll field activities in a crop season and any required baseline data for generating the change in nitrogen rates\n\nEnrollment Assistance\nTo get started, contact Nutrien at sustainableag@nutrien.com\n\nAgronomic/Technical Assistance\nFree technical assistance from a variety of Nutrien staff.","resources":"","factSheet":"","programWebpage":"https://info.nutrienagsolutions.com/sno","organization":"Nutrien"}},{"name":"TH Cattle Company, LLC","livestock":1,"annualCrops":0,"specialtyCrops":0,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Markets & Supply Chains","droughtScore":0,"notes":"Market-focused livestock program; no drought-specific function","details":{"introduction":"Thousand Hills Lifetime Grazed has fully embraced regenerative agriculture to share the health benefits of Lifetime Grazed 100% Grass Fed Beef and to create a sustainable ecosystem with increased soil fertility, biodiversity, clean water retention, and soil carbon sequestration","eligibility":"Geography\nNationwide\n\nEligible Practices\nFencing\nLivestock Pipeline\nPrescribed Grazing\nWatering Facility\n\nAdditionality Requirement\nNo, some participants have already made the regenerative transition.","terms":"Payment Schedule\nDoes not specify\n\nPrice\nThe project will pay producers a market-based incentive per pound to cover the cost differential due to increased grazing management between climate-smart regenerative and conventional beef. Producers will receive market incentive payment of $0.10 per pound hot carcass weight (HCW) in addition to the market-based pricing established with TH Cattle Company and producer. The Northern Great Plains Improved Grazing Carbon Project pays ranchers in MT and WY market rate on the carbon exchange on average $15 per acre for 20 years to implement practices that increase soil carbon sequestration\n\nStackability (With goverment programs and other markets)\nRefer to program category descriptions for general stackability potential. Reach out to the program contact for more information.\n\nCarbon Related Incentive\nNot applicable\n\nContract Length\nThe Partnership for Climate Smart Commodities program is a five year program starting in February 2023.","applicationInstructions":"Data Collected at Enrollment\nInformation on farm, tract, field numbers, producer name, and Core Customer I.D. (CCID). Additionally, participants must certify highly erodible land conservation (HEL) and wetland conservation (WC) compliance via Form AD-1026, Highly Erodible Land Conservation (HELC and Wetland Conservation (WC) Certification.\n\nEnrollment Assistance\nDoes not specify\n\nAgronomic/Technical Assistance\nDoes not specify","resources":"","factSheet":"","programWebpage":"https://thousandhillslifetimegrazed.com/pages/regenerative-agriculture","organization":"TH Cattle Company, LLC"}},{"name":"Food Safety Certification for Specialty Crops Program (FSCSC)","livestock":0,"annualCrops":0,"specialtyCrops":1,"forageHayPasture":0,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Technical Assistance","droughtScore":0,"notes":"Food safety compliance; not drought-related","details":{"introduction":"Did your specialty crop operation recently incur on-farm food safety program expenses related to obtaining or renewing a food safety certification? You may be eligible for financial assistance through USDA\u2019s Food Safety Certification for Specialty Crops Program (FSCSC) for 2025.","eligibility":"To be eligible for FSCSC, an applicant must:\n\nHave obtained or renewed a 2025 food safety certification issued during the 2025 calendar year.\nHave paid eligible expenses. Expenses that have been incurred by the applicant, but have not yet been paid, will not be eligible.\nBe a specialty crop operation; and meet the definition of a small business or a medium-sized business.\nA small business has an average annual monetary value of specialty crops the applicant sold during the 3-year period preceding the program year of no more than $500,000.  \nA medium size business has an average annual monetary value of specialty crops the applicant sold during the 3-year period preceding the program year of at least $500,001 but no more than $1,000,000.\nBe located in the 50 United States, the District of Columbia, the Commonwealth of Puerto Rico, Guam, American Samoa, the U.S. Virgin Islands, and the Commonwealth of the Northern Mariana Islands. \nPlease note, eligible expenses for FSCSC are available by clicking the boxes below. Ineligible expenses include infrastructure improvements, equipment, supplies, salaries and benefits, and fees or penalties for late payment.\n","terms":"The FSCSC program provides financial assistance for specialty crop operations that incur eligible on-farm food safety program expenses related to obtaining or renewing a food safety certification. This program helps offset costs to comply with regulatory requirements and market-driven food safety certification requirements. \n\nFSCSC provides funds to specialty crop operations that incur eligible on-farm food safety program expenses related to obtaining or renewing a food safety certification. FSCSC will cover a percentage of the specialty crop operation\u2019s cost of obtaining or renewing their certification, as well as a percentage of their related expenses.","applicationInstructions":"Eligible specialty crop operations can apply for FSCSC by working directly with the Farm Service Agency office at their\u202flocal USDA Service Center(https://www.farmers.gov/working-with-us/service-center-locator). Applications will be accepted via mail, fax, hand delivery, or electronic means.  \n\nThe following forms are needed to apply for FSCSC (Available below):\n\nFSA-888, Food Safety Certification for Specialty Crops (FSCSC) Program Application: (available soon) This form includes a certification of the applicant\u2019s status as a specialty crop operation and a small or very\u2004small business, and their eligible expenses. Complete the form according to the FSA-888 instructions.\n\nAD-2047, Customer Data Worksheet\n\nSF-3881, ACH Vendor/Miscellaneous Payment Enrollment Form\n\nCCC-860, Socially Disadvantaged, Limited Resource, Beginning and Veteran Farmer or Rancher Certification** **(if applicable)\n\nSupporting Documentation, if requested: Please note that applicants may be required to provide additional documentation to the Farm Service Agency, if necessary, to substantiate the expenses reported on the application. Examples of supporting documentation include paid invoices, purchase receipts, test results, food safety plans, and certifications, training documentation, and other records determined acceptable by FSA.","resources":"https://www.farmers.gov/coronavirus/pandemic-assistance/food-safety/faq","factSheet":"https://www.farmers.gov/sites/default/files/documents/fsa-fscsc-factsheet.pdf","programWebpage":"https://www.farmers.gov/coronavirus/pandemic-assistance/food-safety","organization":"Farm Service Agency"}},{"name":"Grazing Lands Conservation Initiative (GLCI)","livestock":1,"annualCrops":0,"specialtyCrops":0,"forageHayPasture":1,"forestry":0,"irrigatedPerennial":0,"mixedOperations":0,"supportType":"Technical Assistance","droughtScore":1,"notes":"Improves grazing management and forage resilience under drought","details":{"introduction":"NRCS\u2019s Grazing Lands Conservation Initiative (GLCI) was developed as a coordinated effort to identify priority issues, find solutions, and effect change on private grazing land, enhancing existing conservation programs.","eligibility":"","terms":"USDA is reviving and revitalizing GLCI to leverage partner capacity, expertise and technical assistance to expand the footprint of well-managed grazing systems across the country. While some states have been able to use annual funds to support similar agreements, this new structure and additional funding provides a more strategic and comprehensive approach to support grazing systems, reach new and underserved producers.\n\nGLCI also supports the National Grazing Lands Coalition to help state grazing coalitions boost participation from underserved producers; host a Triennial National Grazing Lands Conference; and to act as navigators for grazers seeking additional resources.\u202f \u202f ","applicationInstructions":"USDA Service Centers are locations where you can connect with Farm Service Agency, Natural Resources Conservation Service, or Rural Development employees for your business needs. Enter your state and county below to \ufb01nd your local service center and agency offices. If this locator does not work in your browser, please visit offices.usda.gov.","resources":"","factSheet":"","programWebpage":"https://www.nrcs.usda.gov/programs-initiatives/grazing-lands-conservation-initiative","organization":"Natural Resources Conservation Service"}},{"name":"Organic Transition Initiative Direct Farmer Assistance (OTI)","livestock":1,"annualCrops":1,"specialtyCrops":1,"forageHayPasture":1,"forestry":1,"irrigatedPerennial":1,"mixedOperations":1,"supportType":"Technical Assistance","droughtScore":1,"notes":"Supports soil health and system transitions that improve drought resilience","details":{"introduction":"USDA\u2019s Natural Resources Conservation Service (NRCS) can help you transition to organic through the Organic Transition Initiative (OTI). We\u2019ll also have new organic experts to support NRCS staff and host hands-on organic training and fielding organic-related staff questions.","eligibility":"Farmers, ranchers, forest landowners, and other producers beginning or in the process of transitioning to organic certification.","terms":"The new organic management standard gives you the flexibility to get the assistance and education you need such as attending workshops or requesting help from experts or mentors.\n\nIt supports conservation activities and practices required for organic certification and may provide foregone income reimbursement for dips in production during the transition period.\n\nFor example, the National Organic Standards support composting, outdoor access for livestock, and organic nutrient management which are all covered through the Environmental Quality Incentives Program under the new standard.\n\nFlexible education and training activities can include field days, working alongside organic experts and more. You can work with NRCS field staff, approved technical service providers, and other approved organic partners.\n","applicationInstructions":"Contact your local NRCS office to apply: http://www.farmers.gov/service-locator\n\nHigher payment rates and other options are available for underserved producers including socially disadvantaged, beginning, veteran, and limited resource farmers and ranchers.\u202f","resources":"","factSheet":"https://www.nrcs.usda.gov/sites/default/files/2023-04/2023-NRCS-Organic%20Transition%20Initiative%20Fact%20Sheet.pdf","programWebpage":"https://www.farmers.gov/your-business/organic/organic-transition-initiative/assistance","organization":"Natural Resources Conservation Service"}},{"name":"Western SARE Farmer/Rancher Grant","livestock":1,"annualCrops":1,"specialtyCrops":1,"forageHayPasture":1,"forestry":0,"irrigatedPerennial":1,"mixedOperations":1,"supportType":"Grant","droughtScore":1,"notes":"Provides funding for farmer-led innovation projects, including practices that may improve drought resilience, though not specifically targeted to drought","details":{"introduction":"The Western SARE Farmer/Rancher Research & Education Grant Program focuses on advancing on-farm sustainability solutions by funding innovative producer-driven research and outreach. This grant program involves agricultural producers (main applicants) and technical advisor(s) implementing projects to address identified needs in sustainable agriculture.","eligibility":"WSARE requires that agricultural producers be involved from inception to finish in the planning, design, implementation, and educational outreach of any WSARE-funded project.\n\nFor Farmer/Rancher Grants: The project team must be a minimum of two (2) people and must include: A Producer (Principal Investigator and Applicant) and an Agricultural Professional. The Agricultural Professional must be independent of the Producer and should not submit the application on behalf of the Producer.","terms":"With a Farmer/Rancher Grant, a producer and a technical advisor work together to develop a project\u00a0(1-3 years in scope)\u00a0that conducts\u00a0both research and outreach\u00a0on a sustainable agriculture topic. With the support and guidance of the technical advisor, producers must integrate research and education to conduct on-site/on-farm experiments to address social, environmental, and economic aspects of agricultural sustainability. The goal of this program is to achieve results that can be communicated to other producers and professionals; sustain and improve the environmental quality and natural resource base on which agriculture depends; improve the profitability of producers and associated agricultural businesses; and enhance the quality of life for producers in local communities. Outreach activities may include on-farm/ranch demonstrations, farmer-to-farmer educational activities, and other approaches to assist producer adoption of sustainable agricultural practices.","applicationInstructions":"https://projects.sare.org/","resources":"","factSheet":"","programWebpage":"https://western.sare.org/grants/farmer-rancher/","organization":"Sustainable Agriculture Research and Education"}},{"name":"AgWest New Producer Grant","livestock":1,"annualCrops":1,"specialtyCrops":1,"forageHayPasture":1,"forestry":1,"irrigatedPerennial":1,"mixedOperations":1,"supportType":"Grant","droughtScore":0,"notes":"General support for new producers; not drought-focused","details":{"introduction":"At AgWest Farm Credit, we recognize that a lack of start-up funds can be challenging for many new producers. This grant opportunity celebrates the ingenuity and passion of new producers and helps them bring dreams to fruition. This program was developed for those who have a vision for their operation but lack the funds to put their plans into action.","eligibility":"Be a full- or part-time agriculturalist with two years or less of operational experience or have plans to start an operation within two years of the grant application date.\n\nHave an operation located within AgWest Farm Credit\u2019s territory.\n\nNot be a current AgWest lending customer.\n\nMust be 18 years of age and either a U.S. citizen or a foreign national lawfully admitted for permanent residency or pursuant to certain visas.","terms":"Successful applicants will receive a one-time $15,000 grant to support their operation\u2019s growth.\n","applicationInstructions":"To apply, the applicant must complete the following:\n\n1. Review the Strategic Business Planning guide.\n2. View three recorded webinars covering Financial Statement Basics posted in the Preparing Financials section of AgWestfc.com. \nIncome Statement\nCash Flow Budget\nBalance Sheet Basics\n3. Submit a business plan and cash flow budget Use templates, if needed. \nBusiness Plan (template) \nCash Flow Budget (Excel template) \n4. Answer short essay questions sharing the applicant\u2019s approach to deepening knowledge of their industry, how funds received through this grant will be used to achieve their business plan goals and how their operation will benefit their local community or help others","resources":"","factSheet":"","programWebpage":"https://www.agwestfc.com/about/community-engagement/grants/new-producer-grant","organization":"AgWest Farm Credit"}}];

const FARM_OPERATION_KEYS = [
  { key: "livestock", label: "Livestock" },
  { key: "annualCrops", label: "Annual Crops" },
  { key: "specialtyCrops", label: "Specialty Crops" },
  { key: "forageHayPasture", label: "Forage / Hay / Pasture" },
  { key: "forestry", label: "Forestry / Agroforestry" },
  { key: "irrigatedPerennial", label: "Irrigated Perennial" },
  { key: "mixedOperations", label: "Mixed Operations" },
];

//const SUPPORT_TYPES = [...new Set(programData.map(p => p.supportType).filter(Boolean))].sort();

//const DROUGHT_LABELS = {
//  0: { label: "Not drought-focused", color: "#8c8c8c" },
//  1: { label: "Indirectly relevant", color: "#fa8c16" },
